2444:    $spec = Get-EngineSpec -Name $Engine
2445:    if (-not $spec) {
2446:        $id.Error = "unknown engine '$Engine' (engines: $($script:EngineNames -join ', '))"
2447:        $id.Lineage = Format-Lineage -Provider $id.Provider -Model $id.Model
2448:        return $id
2449:    }
2450:    if ($Provider) { $id.Provider = $Provider; $id.ProviderSource = '-Provider' }
2451:    else { $id.Provider = [string]$spec.DefaultProvider; $id.ProviderSource = 'engine default' }
2452:    if ($Model) { $id.Model = $Model; $id.ModelSource = '-Model' }
2453:    else { $id.Error = "the $Engine engine needs a model: pass -Model <id> (the full model id, e.g. $($spec.ModelExample)) or name it in the roster entry" }
2454:    $id.HostName = [string]$spec.HostName
2455:    $id.WireApi = ''
2456:    $id.BaseUrl = ''
2457:    $pc = New-Object PSObject
2458:    $pc | Add-Member -NotePropertyName 'engine' -NotePropertyValue $Engine
2459:    $pc | Add-Member -NotePropertyName 'launcher' -NotePropertyValue $(if ($Launcher) { $Launcher } else { '' })
2460:    # (wave 23) the engine's own fields - muse: credential_mechanism (D4)
2461:    if ($spec.Adapter -and $spec.Adapter.PSObject.Properties['IdentityConfig'] -and $spec.Adapter.IdentityConfig) {
2462:        $extra = & $spec.Adapter.IdentityConfig
2463:        foreach ($k in @($extra.Keys)) { $pc | Add-Member -NotePropertyName ([string]$k) -NotePropertyValue $extra[$k] }
2464:    }
2465:    $id.ProviderConfig = $pc
2466:    $id.Display = "engine $Engine ($(if ($Launcher) { $Launcher } else { "$($spec.Command) CLI not found" }))"
2467:    $id.ConfigPath = ''
2468:    $id.Lineage = Format-Lineage -Provider $id.Provider -Model $id.Model
2469:    if (-not $id.Error) {
2470:        $id.Resolved = $true
2471:        $id.CompatString = [string]$spec.CompatString
2472:        $id.Fingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes($id.CompatString))
2473:    }
2474:    return $id
2475:}
