2533:# ----------------------------------------------------------------------------- effort vocabularies
2534:#
2535:# -Effort and the purpose presets speak low|medium|high|xhigh. What an endpoint accepts
2536:# is DECLARED, never inferred (no host-wide or model-prefix guess): capability table
2537:# caps-v1 -
2538:#   the built-in openai provider (no user table, no OPENAI_BASE_URL)
2539:#       vocabulary openai for any model (Codex validates its own models)   low medium high xhigh
2540:#   hosts api.z.ai, open.bigmodel.cn
2541:#       vocabulary zai (mapping zai-v1) ONLY for the declared models below  low high max
2542:#       (exact, case-sensitive): medium -> high, xhigh -> max
2543:#   hosts token-plan-ams.xiaomimimo.com, token-plan-cn.xiaomimimo.com, api.xiaomimimo.com
2544:#       vocabulary mimo (mapping mimo-v1) ONLY for the declared models     none low medium
2545:#       below (exact): low, medium, high as is, xhigh -> high               high
2546:#   host ark.ap-southeast.bytepluses.com (BytePlus ModelArk Coding Plan)
2547:#       vocabulary ark (mapping ark-v1) ONLY for the declared models     low medium high
2548:#       below (exact): low, medium, high as is, xhigh -> high
2549:#   host api.kimi.ai (Kimi Code membership)
2550:#       vocabulary kimi (mapping kimi-v1) ONLY for the declared models   low high max
2551:#       below (exact): medium -> high, xhigh -> max
2552:#   host token-plan.ap-southeast-1.maas.aliyuncs.com (Alibaba Model Studio Token Plan)
2553:#       vocabulary alibaba (mapping alibaba-v1) ONLY for the declared    low medium high
2554:#       models below (exact), all four as is. The plan's `auto` router   xhigh
2555:#       is not declared: the endpoint picks its target model, so the accepted effort is unknown.
2556:#   engine:agy (the agy engine, any model)
2557:#       vocabulary model-tier (mapping model-tier): NOTHING is sent - the reasoning tier is
2558:#       part of the agy model id (gemini-3.8-flash-high); effort_sent null. -NativeEffort
2559:#       sends --effort <value> verbatim (agy checks it against the tier itself). The reply
2560:#       schema travels natively (--json-schema): SchemaTransport 'native'.
2561:#   engine:muse (the muse engine: Meta's Muse Code CLI, wave 23)
2562:#       vocabulary muse (mapping muse-v1) ONLY for the live-verified   low medium high
2563:#       subscription models below (exact): all four as is, sent as      xhigh
2564:#       --reasoning-effort <v>. The reply schema travels natively (--output-schema):
2565:#       SchemaTransport 'native'.
2566:# A vocabulary a caps row names but $script:EffortVocabularies lacks is a plan error (a bridge
2567:# defect, never a silently empty mapping).
2568:# Anything else - an undeclared model on a known host, any model on another endpoint -
2569:# has no vocabulary: the run is refused unless -NativeEffort sends a value verbatim.
2570:# Codex's events do not report the effort the endpoint applied: effort_confirmed is null.
2571:$script:EffortCapsVersion = 'caps-v1'
2572:$script:EffortVocabularies = @{
2573:    'openai' = @{ Mapping = 'openai'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'xhigh' } }
2574:    'zai'    = @{ Mapping = 'zai-v1'; Map = @{ 'low' = 'low'; 'medium' = 'high'; 'high' = 'high'; 'xhigh' = 'max' } }
2575:    'mimo'   = @{ Mapping = 'mimo-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'high' } }
2576:    # BytePlus ModelArk Coding Plan (the Codex integration doc: model_reasoning_effort = low | medium | high)
2577:    'ark'    = @{ Mapping = 'ark-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'high' } }
2578:    # Kimi Code (Moonshot) on its Codex base URL: K3 takes low | high | max (the Kimi Code Codex doc)
2579:    'kimi'   = @{ Mapping = 'kimi-v1'; Map = @{ 'low' = 'low'; 'medium' = 'high'; 'high' = 'high'; 'xhigh' = 'max' } }
2580:    # Alibaba Cloud Model Studio Token Plan: every text model takes low | medium | high | xhigh
2581:    # (the Model Studio Codex doc, 2026-09-26)
2582:    'alibaba' = @{ Mapping = 'alibaba-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'xhigh' } }
2583:    # Meta's Muse Code CLI (--reasoning-effort none|minimal|low|medium|high|xhigh|max|ultra)
2584:    'muse'    = @{ Mapping = 'muse-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'xhigh' } }
2585:}
2586:# The model names Kimi Code accepts on https://api.kimi.ai/coding/v1 (its Codex doc; which of them a
2587:# membership unlocks depends on the tier: Plus has k3 at 256K context, Pro adds the 1M window and
2588:# kimi-for-coding-highspeed).
2589:$script:KimiDeclaredModels = @('k3', 'k3-256k', 'kimi-for-coding', 'kimi-for-coding-highspeed')
2590:$script:ZaiDeclaredModels = @('glm-5.3', 'glm-5.3-flash', 'glm-5.3-flashx', 'glm-5.2', 'glm-5.1', 'glm-5', 'glm-5-turbo', 'glm-4.7', 'glm-4.6', 'glm-4.5', 'glm-4.5-air')
2591:$script:MimoDeclaredModels = @('mimo-v2.6-pro', 'mimo-v2.6-flash', 'mimo-v2.6-pro-ultraspeed', 'mimo-v2.5-pro', 'mimo-v2.5')
2592:# The model names the BytePlus ModelArk Coding Plan accepts on its Codex (OpenAI-protocol) base URL
2593:# https://ark.ap-southeast.bytepluses.com/api/coding/v3 (its quick-start guide, 2026-09-24).
2594:$script:ArkPlanDeclaredModels = @('dola-seed-2.0-pro', 'dola-seed-2.0-lite', 'dola-seed-2.0-code', 'bytedance-seed-code', 'glm-5.3-flash', 'glm-5.2', 'glm-5.1', 'kimi-k2.5', 'gpt-oss-120b', 'deepseek-v4.1-flash', 'deepseek-v4-flash', 'deepseek-v4-pro')
2595:# The text models the Alibaba Cloud Model Studio Token Plan (Personal Edition) lists on its
2596:# subscription page and the Codex doc (2026-09-26), without the plan's `auto` router (its target
2597:# model - and so the effort it accepts - is chosen by the endpoint).
2598:# The Muse Code subscription models verified live through `muse exec` (2026-09-25/26): the
2599:# contributor variant (the CLI default; Meta may train on its inputs) and the standard one. The
2600:# docs also list the 1.2 pair and 1.1 - not declared until verified.
2601:$script:MuseDeclaredModels = @('muse-spark-1.3', 'muse-spark-1.3-contributor')
2602:$script:AlibabaTokenPlanDeclaredModels = @('qwen3.8-max', 'qwen3.8-flash', 'qwen3.7-max', 'qwen3.7-plus', 'qwen3.6-flash', 'deepseek-v4.1-flash', 'deepseek-v4-pro', 'deepseek-v4-pro-0813', 'deepseek-v4-flash-0731', 'glm-5.3', 'glm-5.2')
2603:# host -> { Vocabulary; Models ($null = any model); SchemaTransport }. SchemaTransport: how
2604:# the reply schema reaches the endpoint - 'output-schema' (--output-schema; the built-in
2605:# openai enforces it, z.ai accepts it without enforcing) or 'prompt-only' (MiMo rejects a
2606:# json_schema response format: the schema travels in the prompt only). An endpoint not
2607:# in the table is 'prompt-only' (Get-SchemaTransport).
2608:$script:EffortCaps = @{
2609:    'builtin:openai'                = @{ Vocabulary = 'openai'; Models = $null; SchemaTransport = 'output-schema' }
2610:    'api.z.ai'                      = @{ Vocabulary = 'zai'; Models = $script:ZaiDeclaredModels; SchemaTransport = 'output-schema' }
2611:    'open.bigmodel.cn'              = @{ Vocabulary = 'zai'; Models = $script:ZaiDeclaredModels; SchemaTransport = 'output-schema' }
2612:    'token-plan-ams.xiaomimimo.com' = @{ Vocabulary = 'mimo'; Models = $script:MimoDeclaredModels; SchemaTransport = 'prompt-only' }
2613:    'token-plan-cn.xiaomimimo.com'  = @{ Vocabulary = 'mimo'; Models = $script:MimoDeclaredModels; SchemaTransport = 'prompt-only' }
2614:    'api.xiaomimimo.com'            = @{ Vocabulary = 'mimo'; Models = $script:MimoDeclaredModels; SchemaTransport = 'prompt-only' }
2615:    # BytePlus ModelArk Coding Plan (ap-southeast-1): the quota counts only through the /api/coding/v3
2616:    # base URL; the schema travels in the prompt (a json_schema response format is not documented).
2617:    'ark.ap-southeast.bytepluses.com' = @{ Vocabulary = 'ark'; Models = $script:ArkPlanDeclaredModels; SchemaTransport = 'prompt-only' }
2618:    # Kimi Code membership (overseas domain; the China domain api.kimi.com is not declared): the
2619:    # schema travels in the prompt (a json_schema response format on this route is not documented).
2620:    'api.kimi.ai'                   = @{ Vocabulary = 'kimi'; Models = $script:KimiDeclaredModels; SchemaTransport = 'prompt-only' }
2621:    # Alibaba Cloud Model Studio Token Plan (Singapore only): the quota counts only with the plan's own
2622:    # key (sk-sp-...) on this base URL (/compatible-mode/v1, Responses API); a general Model Studio
2623:    # key or base URL bills pay-as-you-go. The schema travels in the prompt.
2624:    'token-plan.ap-southeast-1.maas.aliyuncs.com' = @{ Vocabulary = 'alibaba'; Models = $script:AlibabaTokenPlanDeclaredModels; SchemaTransport = 'prompt-only' }
2625:    'engine:agy'                    = @{ Vocabulary = 'model-tier'; Models = $null; SchemaTransport = 'native' }
2626:    'engine:muse'                   = @{ Vocabulary = 'muse'; Models = $script:MuseDeclaredModels; SchemaTransport = 'native' }
2627:}
2628:
2629:# { Transport ('output-schema' | 'prompt-only'); Basis } for the identity's endpoint;
2630:# 'prompt-only' is the safe default for an endpoint caps-v1 does not declare (a
2631:# json_schema response format it may reject would fail the whole run).
2632:function Get-SchemaTransport {
2633:    param($Identity)
2634:    $hostName = [string]$Identity.HostName
2635:    if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) {
2636:        return [pscustomobject]@{ Transport = $script:EffortCaps[$hostName].SchemaTransport; Basis = "$($script:EffortCapsVersion): $hostName" }
2637:    }
2638:    $label = if ($hostName) { $hostName } else { 'unknown-host' }
2639:    return [pscustomobject]@{ Transport = 'prompt-only'; Basis = "default for an endpoint $($script:EffortCapsVersion) does not declare: $label" }
2640:}
2641:
2642:# { Requested; Sent; Mapping; Caps; Basis; Error }
2643:function Resolve-EffortPlan {
2644:    param($Identity, [string]$Requested, [string]$Native = '')
2645:    $plan = [pscustomobject]@{ Requested = $Requested; Sent = ''; Mapping = ''; Caps = $script:EffortCapsVersion; Basis = ''; Error = '' }
2646:    if ($Native) {
2647:        $plan.Requested = $Native; $plan.Sent = $Native; $plan.Mapping = 'native'; $plan.Basis = '-NativeEffort, sent verbatim'
2648:        return $plan
2649:    }
2650:    $hostName = [string]$Identity.HostName
2651:    $model = [string]$Identity.Model
2652:    $cap = $null
2653:    if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) { $cap = $script:EffortCaps[$hostName] }
2654:    if ($cap -and $cap.Vocabulary -eq 'model-tier') {
2655:        # An engine whose model id carries the reasoning tier: nothing is sent.
2656:        $plan.Sent = $null
2657:        $plan.Mapping = 'model-tier'
2658:        $plan.Basis = "$($script:EffortCapsVersion): engine $($hostName -replace '^engine:', ''), the tier is part of the model id"
2659:        return $plan
2660:    }
2661:    if (-not $cap) {
2662:        $hostLabel = if ($hostName) { $hostName } else { 'unknown-host' }
2663:        # Ordinal order: the same list on Windows PowerShell 5.1 (NLS ignores '-') and pwsh 7 (ICU).
2664:        $declaredHosts = [string[]]@($script:EffortCaps.Keys | Where-Object { $_ -notlike 'engine:*' })
2665:        [Array]::Sort($declaredHosts, [StringComparer]::Ordinal)
2666:        $declared = $declaredHosts -join ', '
2667:        $plan.Error = "no effort vocabulary declared for $hostLabel ($($script:EffortCapsVersion) declares $declared); pass -NativeEffort <value> to send a value verbatim"
2668:        return $plan
2669:    }
2670:    if (($null -ne $cap.Models) -and (($Identity.ModelSource -eq 'unknown') -or -not ($cap.Models -ccontains $model))) {
2671:        $plan.Error = "no effort vocabulary declared for model '$model' on $hostName ($($script:EffortCapsVersion) declares: $($cap.Models -join ', ')); pass -NativeEffort <value> to send a value verbatim"
2672:        return $plan
2673:    }
2674:    $v = $null
2675:    if ($script:EffortVocabularies.ContainsKey([string]$cap.Vocabulary)) { $v = $script:EffortVocabularies[[string]$cap.Vocabulary] }
2676:    if ($null -eq $v) {
2677:        # (wave 23, D10) a caps row whose vocabulary is not declared: loud, never an empty mapping
2678:        $plan.Error = "$($script:EffortCapsVersion) names the effort vocabulary '$($cap.Vocabulary)' for $hostName, but no such vocabulary is declared (a bridge defect); pass -NativeEffort <value> to send a value verbatim"
2679:        return $plan
2680:    }
2681:    $plan.Sent = $v.Map[$Requested]
2682:    $plan.Mapping = $v.Mapping
2683:    $plan.Basis = if ($null -eq $cap.Models) { "$($script:EffortCapsVersion): $hostName, any model" } else { "$($script:EffortCapsVersion): $hostName, $model" }
2684:    return $plan
2685:}
2686:
2687:# ----------------------------------------------------------------------------- peak windows
2688:#
2689:# CODEX_CONSULT_PEAK_<PROVIDER> = "<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>" (the provider
2690:# name upper-cased, every character outside A-Z 0-9 replaced by _), e.g.
2691:# CODEX_CONSULT_PEAK_ZAI="Mon-Fri 14:00-18:00 +08:00". Days: *, a day (Mon), a range
2692:# (Mon-Fri; it may wrap: Fri-Mon) or a comma list of those. Optional
2693:# CODEX_CONSULT_PEAK_<PROVIDER>_EXCEPT = comma-separated YYYY-MM-DD or
2694:# YYYY-MM-DD..YYYY-MM-DD: those calendar dates (in the schedule's offset) are off-peak all
2695:# day. Evaluated ONCE at launch in the fixed offset: start inclusive, end exclusive (24:00
2696:# = midnight); an overnight window (start > end) spans midnight and its day check applies
2697:# to the day it STARTED. peak = $true | $false; $null = no schedule (unknown). A long
2698:# consultation that starts off-peak may still run into the window.
2699:$script:DayNames = @('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat')
2700:
2701:# The clock of the peak evaluations. TEST HOOK: CODEX_CONSULT_NOW = one or more ISO
2702:# timestamps with an offset, comma-separated; the k-th evaluation of a run uses the k-th
2703:# (the last one repeats), so a test can put the early check off-peak and the launch-time
2704:# check inside the window. Unset: the system clock. { Now (DateTimeOffset); Iso; FromEnv;
2705:# Error }. -Peek reads the value the next evaluation would get without consuming it (the
2706:# endpoint-health reading of the preflight and codex-providers.ps1 use it).
2707:$script:ConsultClockCalls = 0
2708:function Get-ConsultClock {
2709:    param([switch]$Peek)
2710:    $raw = [string]$env:CODEX_CONSULT_NOW
2711:    $call = $script:ConsultClockCalls
2712:    if (-not $Peek) { $script:ConsultClockCalls++ }
2713:    if (-not $raw.Trim()) {
2714:        $n = [DateTimeOffset]::Now
2715:        return [pscustomobject]@{ Now = $n; Iso = $n.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $false; Error = '' }
2716:    }
2717:    $items = @($raw.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2718:    $parsed = New-Object System.Collections.Generic.List[DateTimeOffset]
2719:    foreach ($item in $items) {
2720:        $dto = [DateTimeOffset]::MinValue
2721:        if ($item -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?([+-][0-9]{2}:[0-9]{2}|Z)$' -or -not [DateTimeOffset]::TryParse($item, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dto)) {
2722:            return [pscustomobject]@{ Now = $null; Iso = ''; FromEnv = $true; Error = "CODEX_CONSULT_NOW='$raw' is malformed: bad token '$item' (a test hook: ISO timestamps with an offset, e.g. 2026-09-24T13:59:59+08:00, comma-separated)" }
2723:        }
2724:        $parsed.Add($dto)
2725:    }
2726:    $pick = $parsed[[Math]::Min($call, $parsed.Count - 1)]
2727:    return [pscustomobject]@{ Now = $pick; Iso = $pick.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $true; Error = '' }
2728:}
2729:
2730:# Get-PeakStatus at the clock's current reading; adds EvaluatedAt and marks a peak_source
2731:# 'env (CODEX_CONSULT_NOW)' when the test hook set the time. Error covers both inputs.
2732:function Get-PeakStatusNow {
2733:    param([string]$Provider)
2734:    $clock = Get-ConsultClock
2735:    if ($clock.Error) { return [pscustomobject]@{ Peak = $null; Schedule = ''; Source = 'none'; Variable = ''; Local = ''; Detail = ''; Error = $clock.Error; EvaluatedAt = '' } }
2736:    $st = Get-PeakStatus -Provider $Provider -UtcNow $clock.Now.UtcDateTime
2737:    if ($clock.FromEnv -and $st.Source -eq 'env') { $st.Source = 'env (CODEX_CONSULT_NOW)' }
2738:    $st | Add-Member -NotePropertyName 'EvaluatedAt' -NotePropertyValue $clock.Iso
2739:    return $st
2740:}
2741:
2742:function Get-PeakVariableName {
2743:    param([string]$Provider)
2744:    return ('CODEX_CONSULT_PEAK_' + ($Provider.ToUpperInvariant() -replace '[^A-Z0-9]', '_'))
2745:}
