2747:# { Days (bool[7], index = [int][DayOfWeek]); Start; End (minutes); Offset; Error }
2748:function ConvertFrom-PeakSpec {
2749:    param([string]$Spec, [string]$VarName)
2750:    $r = [pscustomobject]@{ Days = $null; Start = 0; End = 0; Offset = [TimeSpan]::Zero; Error = '' }
2751:    $format = "expected '<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>', e.g. 'Mon-Fri 14:00-18:00 +08:00'"
2752:    $trimmed = ([string]$Spec).Trim()
2753:    $tokens = @($trimmed -split '\s+')
2754:    if ($tokens.Count -ne 3) {
2755:        $r.Error = "$VarName='$Spec' is malformed: bad token '$trimmed' ($($tokens.Count) field(s) instead of 3); $format"
2756:        return $r
2757:    }
2758:    $dayHelp = 'day names are Mon Tue Wed Thu Fri Sat Sun, a range Mon-Fri, a list Mon,Wed or *'
2759:    $days = New-Object 'bool[]' 7
2760:    if ($tokens[0] -eq '*') {
2761:        for ($d = 0; $d -lt 7; $d++) { $days[$d] = $true }
2762:    } else {
2763:        foreach ($item in $tokens[0].Split(',')) {
2764:            $mRange = [regex]::Match($item, '^([A-Za-z]{3})-([A-Za-z]{3})$')
2765:            if ($mRange.Success) {
2766:                $a = [Array]::IndexOf($script:DayNames, $mRange.Groups[1].Value.ToLowerInvariant())
2767:                $b = [Array]::IndexOf($script:DayNames, $mRange.Groups[2].Value.ToLowerInvariant())
2768:                if ($a -lt 0 -or $b -lt 0) { $r.Error = "$VarName='$Spec' is malformed: bad token '$item' ($dayHelp); $format"; return $r }
2769:                $d = $a
2770:                while ($true) { $days[$d] = $true; if ($d -eq $b) { break }; $d = ($d + 1) % 7 }
2771:                continue
2772:            }
2773:            $one = -1
2774:            if ($item -match '^[A-Za-z]{3}$') { $one = [Array]::IndexOf($script:DayNames, $item.ToLowerInvariant()) }
2775:            if ($one -lt 0) { $r.Error = "$VarName='$Spec' is malformed: bad token '$item' ($dayHelp); $format"; return $r }
2776:            $days[$one] = $true
2777:        }
2778:    }
2779:    $mt = [regex]::Match($tokens[1], '^([0-9]{2}):([0-9]{2})-([0-9]{2}):([0-9]{2})$')
2780:    $timeOk = $mt.Success
2781:    if ($timeOk) {
2782:        $sh = [int]$mt.Groups[1].Value; $sm = [int]$mt.Groups[2].Value; $eh = [int]$mt.Groups[3].Value; $em = [int]$mt.Groups[4].Value
2783:        $timeOk = ($sh -le 23 -and $sm -le 59 -and $em -le 59 -and ($eh -le 23 -or ($eh -eq 24 -and $em -eq 0)))
2784:        if ($timeOk) {
2785:            $r.Start = $sh * 60 + $sm
2786:            $r.End = $eh * 60 + $em
2787:            if ($r.Start -eq $r.End) { $timeOk = $false }
2788:        }
2789:    }
2790:    if (-not $timeOk) { $r.Error = "$VarName='$Spec' is malformed: bad token '$($tokens[1])' (a window HH:MM-HH:MM, 00:00..23:59, end up to 24:00, start <> end); $format"; return $r }
2791:    $mo = [regex]::Match($tokens[2], '^([+-])([0-9]{2}):([0-9]{2})$')
2792:    $offOk = $mo.Success
2793:    if ($offOk) {
2794:        $oh = [int]$mo.Groups[2].Value; $om = [int]$mo.Groups[3].Value
2795:        $offOk = ($om -le 59 -and ($oh * 60 + $om) -le 14 * 60)
2796:        if ($offOk) {
2797:            $r.Offset = New-Object TimeSpan($oh, $om, 0)
2798:            if ($mo.Groups[1].Value -eq '-') { $r.Offset = $r.Offset.Negate() }
2799:        }
2800:    }
2801:    if (-not $offOk) { $r.Error = "$VarName='$Spec' is malformed: bad token '$($tokens[2])' (a UTC offset +HH:MM or -HH:MM, at most 14:00); $format"; return $r }
2802:    $r.Days = $days
2803:    return $r
2804:}
