2806:# { Intervals (list of @(start, end) dates, inclusive); Error }. Ranges are kept as
2807:# intervals - any length, never expanded; only end < start is refused.
2808:function ConvertFrom-PeakExceptions {
2809:    param([string]$Text, [string]$VarName)
2810:    $list = New-Object System.Collections.Generic.List[object]
2811:    $r = [pscustomobject]@{ Intervals = $list; Error = '' }
2812:    $format = 'expected comma-separated YYYY-MM-DD or YYYY-MM-DD..YYYY-MM-DD'
2813:    foreach ($raw in ([string]$Text).Split(',')) {
2814:        $item = $raw.Trim()
2815:        if (-not $item) { continue }
2816:        $parts = @($item -split '\.\.')
2817:        $parsed = New-Object System.Collections.Generic.List[datetime]
2818:        foreach ($p in $parts) {
2819:            $dt = [datetime]::MinValue
2820:            if ($p -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' -or -not [datetime]::TryParseExact($p, 'yyyy-MM-dd', $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) {
2821:                $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format)"; return $r
2822:            }
2823:            $parsed.Add($dt.Date)
2824:        }
2825:        if ($parsed.Count -gt 2 -or ($parsed.Count -eq 2 -and $parsed[1] -lt $parsed[0])) {
2826:            $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format; a range must not run backwards)"; return $r
2827:        }
2828:        $list.Add(@($parsed[0], $parsed[$parsed.Count - 1]))
2829:    }
2830:    return $r
2831:}
2832:
2833:# { Peak ($true | $false | $null); Schedule; Source ('env'|'none'); Variable; Local;
2834:#   Detail; Error }. -Spec / -Except replace the environment (tests).
2835:function Get-PeakStatus {
2836:    param([string]$Provider, [datetime]$UtcNow = [datetime]::UtcNow, [string]$Spec = $null, [string]$Except = $null)
2837:    $st = [pscustomobject]@{ Peak = $null; Schedule = ''; Source = 'none'; Variable = ''; Local = ''; Detail = 'no schedule'; Error = '' }
2838:    if (-not $Provider) { $st.Detail = 'provider unknown'; return $st }
2839:    $var = Get-PeakVariableName $Provider
2840:    $st.Variable = $var
2841:    if (-not $PSBoundParameters.ContainsKey('Spec')) { $Spec = [Environment]::GetEnvironmentVariable($var) }
2842:    if (-not $PSBoundParameters.ContainsKey('Except')) { $Except = [Environment]::GetEnvironmentVariable($var + '_EXCEPT') }
2843:    if (-not $Spec -or -not $Spec.Trim()) { return $st }
2844:    $parsed = ConvertFrom-PeakSpec -Spec $Spec -VarName $var
2845:    if ($parsed.Error) { $st.Error = $parsed.Error; return $st }
2846:    $exceptions = $null
2847:    if ($Except -and $Except.Trim()) {
2848:        $exceptions = ConvertFrom-PeakExceptions -Text $Except -VarName ($var + '_EXCEPT')
2849:        if ($exceptions.Error) { $st.Error = $exceptions.Error; return $st }
2850:    }
2851:    $st.Source = 'env'
2852:    $st.Schedule = $Spec.Trim()
2853:    if ($exceptions) { $st.Schedule += "; except $($Except.Trim())" }
2854:    $utc = $UtcNow
2855:    if ($utc.Kind -eq [DateTimeKind]::Local) { $utc = $utc.ToUniversalTime() }
2856:    $local = $utc.Add($parsed.Offset)
2857:    $sign = if ($parsed.Offset -lt [TimeSpan]::Zero) { '-' } else { '+' }
2858:    $st.Local = $local.ToString('yyyy-MM-dd HH:mm ddd', $script:Invariant) + " $sign" + $parsed.Offset.Duration().ToString('hh\:mm', $script:Invariant)
2859:    $tod = $local.TimeOfDay.TotalMinutes
2860:    $dow = [int]$local.DayOfWeek
2861:    $prev = ($dow + 6) % 7
2862:    if ($parsed.Start -lt $parsed.End) {
2863:        $inside = ($parsed.Days[$dow] -and $tod -ge $parsed.Start -and $tod -lt $parsed.End)
2864:    } else {
2865:        $inside = (($parsed.Days[$dow] -and $tod -ge $parsed.Start) -or ($parsed.Days[$prev] -and $tod -lt $parsed.End))
2866:    }
2867:    $dateKey = $local.ToString('yyyy-MM-dd', $script:Invariant)
2868:    $exceptionHit = $false
2869:    if ($exceptions) {
2870:        foreach ($iv in $exceptions.Intervals) { if ($local.Date -ge $iv[0] -and $local.Date -le $iv[1]) { $exceptionHit = $true; break } }
2871:    }
2872:    if ($exceptionHit) {
2873:        $st.Peak = $false
2874:        $st.Detail = "exception date $dateKey (off-peak all day)"
2875:    } elseif ($inside) {
2876:        $st.Peak = $true
2877:        $st.Detail = 'inside the peak window'
2878:    } else {
2879:        $st.Peak = $false
2880:        $st.Detail = 'outside the peak window'
2881:    }
2882:    return $st
2883:}
