2885:# ----------------------------------------------------------------------------- provider availability
2886:#
2887:# Is a provider usable at all - are its credentials present? Decided locally, never over
2888:# the network:
2889:#   openai (built in), or a table with requires_openai_auth = true
2890:#                 `<codex> login status` (Codex reads its own stored login; timeout
2891:#                 15 s): exit 0 and a "Logged in" line -> ok; anything else -> missing
2892:#   other tables  env_key names an environment variable that is set and non-empty, or
2893:#                 the table carries experimental_bearer_token -> ok; else missing
2894:# A provider that needs no credentials at all (a local endpoint without env_key) reads as
2895:# missing: pass -SkipPreflight for it, or declare it in the reviewer roster with
2896:# "auth": "none" (-Anonymous: ok, "declared anonymous in the roster" - only for a table
2897:# without env_key and bearer token; a table WITH env_key still needs the variable).
2898:# What credentials cannot show - revoked keys,
2899:# exhausted plans - comes from the ledgers: failures are classified (auth, quota,
2900:# capability, transport, unknown) and read back per ENDPOINT (Get-EndpointHealth).
2901:
2902:function Resolve-CodexLauncher {
2903:    param([string]$Explicit)
2904:    # An explicit launcher (-CodexExe, then CODEX_CONSULT_EXE) that does not resolve is an
2905:    # error, never a silent fall-through to whatever `codex` is on PATH.
2906:    $explicitSources = @(@{ value = $Explicit; label = '-CodexExe' }, @{ value = $env:CODEX_CONSULT_EXE; label = 'CODEX_CONSULT_EXE' })
2907:    foreach ($source in $explicitSources) {
2908:        $candidate = [string]$source.value
2909:        if ($candidate) {
2910:            if (Test-Path -LiteralPath $candidate) { return (Resolve-Path -LiteralPath $candidate).Path }
2911:            $cmd = Get-Command $candidate -CommandType Application -ErrorAction SilentlyContinue
2912:            if ($cmd) { return $cmd.Source }
2913:            Stop-WithError "$($source.label) '$candidate' is not a file and not an application on PATH."
2914:        }
2915:    }
2916:    # On Windows, Get-Command 'codex' resolves to codex.ps1 (the npm shim), which
2917:    # Start-Process cannot launch; ask for the native exe / cmd shim first.
2918:    $names = if ($script:OnWindows) { @('codex.exe', 'codex.cmd', 'codex.bat', 'codex') } else { @('codex') }
2919:    foreach ($name in $names) {
2920:        $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue
2921:        if ($cmd) { return $cmd.Source }
2922:    }
2923:    return $null
2924:}
2925:
2926:function New-CredentialResult {
2927:    param([string]$State, [string]$Reason)
2928:    $prefix = @{ ok = 'ok: '; missing = 'missing: '; unknown = 'unknown: ' }[$State]
2929:    return [pscustomobject]@{ State = $State; Reason = $Reason; Detail = ($prefix + $Reason) }
2930:}
2931:
2932:# `<launcher> login status` with a timeout; stdout and stderr are both read (the status
2933:# line may come on either) and decoded as UTF-8 (the Codex CLI writes UTF-8; the default
2934:# would be the console code page). { State ok|missing|unknown; Reason; Detail }.
2935:function Get-CodexLoginStatus {
2936:    param([string]$Launcher, [int]$TimeoutSec = 15)
2937:    if (-not $Launcher) { return (New-CredentialResult 'unknown' 'codex CLI not found, `codex login status` could not run') }
2938:    $p = $null
2939:    try {
2940:        $psi = New-Object System.Diagnostics.ProcessStartInfo
2941:        $psi.FileName = $Launcher
2942:        $psi.Arguments = 'login status'
2943:        $psi.UseShellExecute = $false
2944:        $psi.CreateNoWindow = $true
2945:        $psi.RedirectStandardInput = $true
2946:        $psi.RedirectStandardOutput = $true
2947:        $psi.RedirectStandardError = $true
2948:        $psi.StandardOutputEncoding = $script:Utf8NoBom
2949:        $psi.StandardErrorEncoding = $script:Utf8NoBom
2950:        $p = [System.Diagnostics.Process]::Start($psi)
2951:    } catch {
2952:        return (New-CredentialResult 'unknown' "``codex login status`` could not be started ($(ConvertTo-OneLine $_.Exception.Message))")
2953:    }
2954:    try {
2955:        try { $p.StandardInput.Close() } catch { }
2956:        $outTask = $p.StandardOutput.ReadToEndAsync()
2957:        $errTask = $p.StandardError.ReadToEndAsync()
2958:        if (-not $p.WaitForExit($TimeoutSec * 1000)) {
2959:            $null = Stop-ProcessTree -Process $p
2960:            return (New-CredentialResult 'unknown' "``codex login status`` did not finish within $TimeoutSec s")
2961:        }
2962:        $p.WaitForExit()
2963:        $null = $outTask.Wait(5000)
2964:        $null = $errTask.Wait(5000)
2965:        $lines = @((([string]$outTask.Result) + "`n" + ([string]$errTask.Result)) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2966:        $loggedIn = @($lines | Where-Object { $_ -cmatch 'Logged in' }) | Select-Object -First 1
2967:        if ($p.ExitCode -eq 0 -and $loggedIn) { return (New-CredentialResult 'ok' $loggedIn) }
2968:        $first = if ($lines.Count -gt 0) { $lines[0] } else { "exit $($p.ExitCode)" }
2969:        return (New-CredentialResult 'missing' $first)
2970:    } finally {
2971:        $p.Dispose()
2972:    }
2973:}
2974:
2975:# Credentials of a provider: $Table is its [model_providers.<name>] table object ($null for
2976:# the built-in openai without one). $LoginCache (a hashtable) avoids running
2977:# `login status` twice in one listing. -Anonymous: the reviewer roster declares the endpoint
2978:# credential-free ("auth": "none").
2979:function Get-ProviderCredential {
2980:    param([string]$Name, $Table, [string]$Launcher, [hashtable]$LoginCache = $null, [int]$TimeoutSec = 15, [switch]$Anonymous)
2981:    $openaiAuth = ($Name -ceq 'openai')
2982:    if (-not $openaiAuth -and $Table) {
2983:        $ro = $Table.Entries['requires_openai_auth']
2984:        if ($Table.Entries.ContainsKey('requires_openai_auth') -and $ro.Supported -and $ro.Kind -eq 'boolean' -and $ro.Value -ceq 'true') { $openaiAuth = $true }
2985:    }
2986:    if ($openaiAuth) {
2987:        if ($LoginCache -and $LoginCache.ContainsKey('login')) { return $LoginCache['login'] }
2988:        $r = Get-CodexLoginStatus -Launcher $Launcher -TimeoutSec $TimeoutSec
2989:        if ($LoginCache) { $LoginCache['login'] = $r }
2990:        return $r
2991:    }
2992:    if (-not $Table) { return (New-CredentialResult 'unknown' "no [model_providers.$Name] table") }
2993:    $ek = Get-TomlString -Table $Table -Key 'env_key'
2994:    $bt = Get-TomlString -Table $Table -Key 'experimental_bearer_token'
2995:    $envName = ''
2996:    if ($ek.Present -and -not $ek.Reason) { $envName = $ek.Value.Trim() }
2997:    if ($envName) {
2998:        $v = [Environment]::GetEnvironmentVariable($envName)
2999:        if ($v -and $v.Trim()) { return (New-CredentialResult 'ok' "env $envName set") }
3000:    }
3001:    if ($bt.Present -and -not $bt.Reason -and $bt.Value) { return (New-CredentialResult 'ok' 'bearer token in config') }
3002:    if ($envName) { return (New-CredentialResult 'missing' "env $envName not set") }
3003:    if ($Anonymous) { return (New-CredentialResult 'ok' 'declared anonymous in the roster') }
3004:    return (New-CredentialResult 'missing' 'no env_key/bearer token in the table')
3005:}
