3007:# ----------------------------------------------------------------------------- engines
3008:#
3009:# The CLI that carries a consultation (0.4.0, ROADMAP R10). One row per engine; `codex` is
3010:# the default and its path through codex-consult.ps1 is the 0.3.0 one. Every other engine is
3011:# driven through the same adapter interface (the Adapter functions named in its row), so a
3012:# further engine (e.g. `claude`) is one more row plus its adapter functions. EVERY turn of an
3013:# engine - the main turn, a denial retry, a format repair - goes through them (wave 23, D1/D2):
3014:#   Argv        the argv of a turn, from ONE turn-options object (New-EngineTurnOptions: Model,
3015:#               Mode, Thread, PromptFile, Schema, Effort, NativeEffort, MaxSteps)
3016:#   Stdin       the text written to the turn's stdin (agy: the prompt as one NDJSON line; muse:
3017:#               nothing - its prompt travels in the turn's own prompt file)
3018:#   Events      the event-stream parser -> a normalized turn record (Thread, Usage, Error, ...)
3019:#   Outcome     the failure rules of a turn (-Events -ExitCode -StderrText -Pre -ExpectThread
3020:#               -ExpectModel)
3021:#   Credential  the sign-in check of the preflight (-Launcher -TimeoutSec)
3022:#   Harness     (optional) reviewer.harness (-Launcher); else the launcher's file version
3023:#   IdentityConfig  (optional) extra reviewer.provider_config fields (an ordered hashtable)
3024:#   LaunchBlock (optional) the launch invariant: '' or the refusal (Get-EngineLaunchBlock)
3025:# Row fields: Name, Label (handoff header / author), Prefix (handoff file names
3026:# NN-<prefix>-<slug>.*), Command (first word of the ledger `command`), ExeEnv (launcher
3027:# override), LauncherNames (PATH lookup, in order), InstallLaunchers (the vendor's install
3028:# locations, tried after PATH: { Env; Rel }), Modes, DefaultMode ('' = automatic: fork when a
3029:# parent exists), Sandboxes, Transports (-SchemaTransport values), HostName (caps-v1 key),
3030:# CompatString (the provider fingerprint's input), DefaultProvider (the lineage label without
3031:# -Provider), ModelExample, DenialRetry (the engine can take a denial-retry turn),
3032:# PromptTransport (stdin | file), LocalSignIn (the sign-in check reads local files only: it
3033:# runs under -NoNetwork too), StepsFlag (the model-step cap flag -MaxModelSteps sends; '' = the
3034:# engine has none: -MaxModelSteps is refused), HasUsage (its stream reports token usage), and
3035:# the engine's own wording (D11): PromptVia, ReplySource,
3036:# SchemaFlag, ThreadFlag, ThreadNoun, ReadOnlyNote (the -Sandbox refusal), SandboxRecord (the
3037:# ledger's `sandbox`), TreeNote (the tree check's closing words), ToolsLine (the prompt's tools
3038:# line).
3039:#
3040:#   agy   Google's Antigravity CLI: `agy -p= --input-format stream-json --output-format
3041:#         stream-json --model <m> [--json-schema <schema>] --print-timeout 0 --sandbox
3042:#         --disable-slash-commands [--conversation <thread>] [--effort <v>]`, the prompt as
3043:#         ONE NDJSON line on stdin, the reply = the LAST (and only) `result` event's
3044:#         structured_output (never its `response` text when structured_output is there).
3045:#         Read-only is NOT enforced by agy (--sandbox restricts the terminal only): the
3046:#         bridge's tree check fails a run that changed the working tree (tracked or
3047:#         untracked files) or the collab directory; gitignored paths, submodules and files
3048:#         outside the repository stay unmonitored.
3049:#
3050:#   muse  Meta's Muse Code CLI (wave 23): `muse exec --json --prompt-file <P> [--output-schema
3051:#         <S>] --model <m> [--reasoning-effort <e>] --no-foreign-personal-context
3052:#         --disable-web-tools --disable-write --disable-shell --approval-mode never
3053:#         [--max-model-steps <n>] [--session-id <thread>]`, run in the repository root with an
3054:#         EMPTY stdin: the prompt is the turn's own prompt file. The stream is MSP JSONL
3055:#         (schema_version 1 only); the reply = the text of the ONE run_terminal record
3056:#         (run.terminal.completed); the thread = the ONE session stream id. The subscription
3057:#         bills through the browser sign-in only: an API key in the environment refuses the run
3058:#         (Get-MuseLaunchBlock, D4). No denial retry (its write, shell and web tools are off);
3059:#         the same tree check as agy (reads - read_file is not confined to the repository -,
3060:#         gitignored paths, submodules and files outside the repository stay unmonitored).
3061:$script:EngineNames = @('codex', 'agy', 'muse')
3062:$script:Engines = @{
3063:    'codex' = [pscustomobject]@{
3064:        Name = 'codex'; Label = 'Codex'; Prefix = 'codex'; Command = 'codex'; ExeEnv = 'CODEX_CONSULT_EXE'
3065:        LauncherNames = $(if ($script:OnWindows) { @('codex.exe', 'codex.cmd', 'codex.bat', 'codex') } else { @('codex') })
3066:        InstallLaunchers = @()
3067:        Modes = @('new', 'resume', 'fork'); DefaultMode = ''; Sandboxes = @('read-only', 'workspace-write')
3068:        Transports = @('output-schema', 'prompt-only'); HostName = ''; CompatString = ''; DefaultProvider = ''; ModelExample = 'gpt-5.1'
3069:        DenialRetry = $false; PromptTransport = 'stdin'; LocalSignIn = $false; StepsFlag = ''; HasUsage = $true
3070:        PromptVia = 'prompt on stdin'; ReplySource = ''; SchemaFlag = '--output-schema'; ThreadFlag = ''; ThreadNoun = 'thread'
3071:        ReadOnlyNote = ''; SandboxRecord = ''; TreeNote = ''; ToolsLine = ''
3072:        Adapter = $null
3073:    }
3074:    'agy'   = [pscustomobject]@{
3075:        Name = 'agy'; Label = 'Gemini (agy)'; Prefix = 'agy'; Command = 'agy'; ExeEnv = 'CODEX_CONSULT_AGY_EXE'
3076:        LauncherNames = $(if ($script:OnWindows) { @('agy.exe', 'agy.cmd', 'agy.bat', 'agy') } else { @('agy') })
3077:        InstallLaunchers = @()
3078:        Modes = @('new', 'resume'); DefaultMode = 'new'; Sandboxes = @('read-only')
3079:        Transports = @('native', 'prompt-only'); HostName = 'engine:agy'; CompatString = 'cc-engine-v1|agy'; DefaultProvider = 'gemini'; ModelExample = 'gemini-3.8-flash-high'
3080:        DenialRetry = $true; PromptTransport = 'stdin'; LocalSignIn = $false; StepsFlag = ''; HasUsage = $true
3081:        PromptVia = 'prompt on stdin as one NDJSON line'
3082:        ReplySource = "the result event's structured_output (else its response text)"
3083:        SchemaFlag = '--json-schema'; ThreadFlag = '--conversation'; ThreadNoun = 'conversation'
3084:        ReadOnlyNote = "its --sandbox restricts the terminal only; the bridge's tree check fails a run that writes"
3085:        SandboxRecord = 'read-only (requested; enforced by evidence for tracked and untracked files and the collab directory, not for gitignored paths, submodules or files outside the repository; agy --sandbox restricts the terminal only)'
3086:        TreeNote = "agy's sandbox does not block writes"
3087:        # agy's print mode auto-denies a tool it cannot grant and then ends the turn with no
3088:        # output (F11), and its --sandbox does not block file writes (F12): say both up front.
3089:        ToolsLine = 'Tools: you may read files of the repository; you have NO permission to run commands in this consultation - never call run_command; make NO file changes; a check that needs a command belongs under `## Requested checks`.'
3090:        Adapter = [pscustomobject]@{ Argv = 'New-AgyArgv'; Stdin = 'ConvertTo-AgyStdin'; Events = 'Read-AgyEvents'; Outcome = 'Get-AgyTurnOutcome'; Credential = 'Get-AgyModelsStatus'; Harness = ''; IdentityConfig = ''; LaunchBlock = '' }
3091:    }
3092:    'muse'  = [pscustomobject]@{
3093:        Name = 'muse'; Label = 'Meta Muse (muse)'; Prefix = 'muse'; Command = 'muse'; ExeEnv = 'CODEX_CONSULT_MUSE_EXE'
3094:        LauncherNames = $(if ($script:OnWindows) { @('muse.cmd', 'muse.exe', 'muse') } else { @('muse') })
3095:        # The vendor installs muse.cmd into %LOCALAPPDATA%\Programs\muse and adds that directory to
3096:        # the USER Path - which a bridge started before the install does not see (D3).
