3119:# The launcher of an engine: $Explicit (codex: -CodexExe; others: -EngineExe), then the
3120:# engine's ExeEnv variable, then its LauncherNames on PATH, then (wave 23, D3) its vendor
3121:# install locations (InstallLaunchers: muse - %LOCALAPPDATA%\Programs\muse\muse.cmd on
3122:# Windows). An explicit launcher that does not resolve is an error (never a silent
3123:# fall-through to PATH); $null when none is found.
3124:function Resolve-EngineLauncher {
3125:    param([string]$Engine, [string]$Explicit = '')
3126:    if (-not $Engine -or $Engine -eq 'codex') { return (Resolve-CodexLauncher -Explicit $Explicit) }
3127:    $spec = Get-EngineSpec -Name $Engine
3128:    if (-not $spec) { return $null }
3129:    $sources = @(@{ value = $Explicit; label = '-EngineExe' }, @{ value = [Environment]::GetEnvironmentVariable($spec.ExeEnv); label = $spec.ExeEnv })
3130:    foreach ($source in $sources) {
3131:        $candidate = [string]$source.value
3132:        if ($candidate) {
3133:            if (Test-Path -LiteralPath $candidate) { return (Resolve-Path -LiteralPath $candidate).Path }
3134:            $cmd = Get-Command $candidate -CommandType Application -ErrorAction SilentlyContinue
3135:            if ($cmd) { return @($cmd)[0].Source }
3136:            Stop-WithError "$($source.label) '$candidate' is not a file and not an application on PATH."
3137:        }
3138:    }
3139:    foreach ($name in @($spec.LauncherNames)) {
3140:        $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue
3141:        if ($cmd) { return @($cmd)[0].Source }
3142:    }
3143:    foreach ($il in @($spec.InstallLaunchers)) {
3144:        if ($null -eq $il) { continue }
3145:        $base = [string][Environment]::GetEnvironmentVariable([string]$il.Env)
3146:        if (-not $base.Trim()) { continue }
3147:        $candidate = Join-Path $base ([string]$il.Rel)
3148:        if (Test-Path -LiteralPath $candidate -PathType Leaf) { return (Resolve-Path -LiteralPath $candidate).Path }
3149:    }
3150:    return $null
3151:}
