3153:# The engine -EngineExe names (wave 23, D3): the SELECTED engine other than codex - -Engine's
3154:# when given (codex is refused: it takes -CodexExe); else the one the run can select: the
3155:# roster entry of -Provider (codex-providers: of the -Provider row), else the only engine other
3156:# than codex among the roster's entries. None or several -> refused ("pass -Engine <name>").
3157:# { Engine; Error }.
3158:function Resolve-EngineExeBinding {
3159:    param([string]$Engine = '', $Roster = $null, [string]$Provider = '', [string]$Model = '')
3160:    $r = [pscustomobject]@{ Engine = ''; Error = '' }
3161:    $others = @($script:EngineNames | Where-Object { $_ -ne 'codex' })
3162:    if ($Engine) {
3163:        if ($Engine -eq 'codex') { $r.Error = "-EngineExe names the launcher of an engine other than codex ($($others -join ', ')); codex takes -CodexExe"; return $r }
3164:        $r.Engine = $Engine
3165:        return $r
3166:    }
3167:    if ($Provider) {
3168:        $pe = Find-RosterEntry -Roster $Roster -Provider $Provider -Model $Model
3169:        if ($pe -and $pe.Engine -ne 'codex') { $r.Engine = [string]$pe.Engine; return $r }
3170:        if ($pe) { $r.Error = "-EngineExe: the roster entry $($pe.Position) for -Provider $Provider is engine codex, which takes -CodexExe"; return $r }
3171:    }
3172:    $used = New-Object System.Collections.Generic.List[string]
3173:    if ($Roster -and $Roster.Exists) {
3174:        foreach ($e in @($Roster.Entries)) { $en = [string]$e.Engine; if ($en -and $en -ne 'codex' -and -not $used.Contains($en)) { $used.Add($en) } }
3175:    }
3176:    if ($used.Count -eq 1) { $r.Engine = $used[0]; return $r }
3177:    if ($used.Count -gt 1) { $r.Error = "-EngineExe is ambiguous: the reviewer roster has entries of the engines $($used.ToArray() -join ' and '); pass -Engine <$($others -join '|')> to name the one it launches" }
3178:    else { $r.Error = "-EngineExe names the launcher of an engine other than codex: pass -Engine <$($others -join '|')> with it" }
3179:    return $r
3180:}
