3209:# `agy models` with a timeout (a network round-trip, usually ~2 s but observed at 1.7-15+ s,
3210:# hence 45 s): exit 0 and at least one "<id><TAB><name>" line -> ok "signed in (N models)";
3211:# output mentioning login / sign in / auth / unauthenticated -> missing; anything else (and a
3212:# timeout) -> unknown. stdout and stderr are read as UTF-8. { State; Reason; Detail } like
3213:# Get-CodexLoginStatus.
3214:$script:AgyModelsTimeoutSec = 45
3215:function Get-AgyModelsStatus {
3216:    param([string]$Launcher, [int]$TimeoutSec = 45)
3217:    if (-not $Launcher) { return (New-CredentialResult 'missing' 'agy CLI not found on PATH') }
3218:    $p = $null
3219:    try {
3220:        $psi = New-Object System.Diagnostics.ProcessStartInfo
3221:        $psi.FileName = $Launcher
3222:        $psi.Arguments = 'models'
3223:        $psi.UseShellExecute = $false
3224:        $psi.CreateNoWindow = $true
3225:        $psi.RedirectStandardInput = $true
3226:        $psi.RedirectStandardOutput = $true
3227:        $psi.RedirectStandardError = $true
3228:        $psi.StandardOutputEncoding = $script:Utf8NoBom
3229:        $psi.StandardErrorEncoding = $script:Utf8NoBom
3230:        $p = [System.Diagnostics.Process]::Start($psi)
3231:    } catch {
3232:        return (New-CredentialResult 'unknown' "``agy models`` could not be started ($(ConvertTo-OneLine $_.Exception.Message))")
3233:    }
3234:    try {
3235:        try { $p.StandardInput.Close() } catch { }
3236:        $outTask = $p.StandardOutput.ReadToEndAsync()
3237:        $errTask = $p.StandardError.ReadToEndAsync()
3238:        if (-not $p.WaitForExit($TimeoutSec * 1000)) {
3239:            $null = Stop-ProcessTree -Process $p
3240:            return (New-CredentialResult 'unknown' "``agy models`` did not finish within $TimeoutSec s")
3241:        }
3242:        $p.WaitForExit()
3243:        $null = $outTask.Wait(5000)
3244:        $null = $errTask.Wait(5000)
3245:        $outLines = @(([string]$outTask.Result) -split "`r?`n" | Where-Object { $_ -and $_.Trim() })
3246:        $allLines = @((([string]$outTask.Result) + "`n" + ([string]$errTask.Result)) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
3247:        $models = @($outLines | Where-Object { $_ -match '^\S+\t' })
3248:        if ($p.ExitCode -eq 0 -and $models.Count -ge 1) { return (New-CredentialResult 'ok' "signed in ($($models.Count) models)") }
3249:        $authLine = @($allLines | Where-Object { $_ -match '(?i)log ?in|sign in|signed in|\bauth|unauthenticated' }) | Select-Object -First 1
3250:        if ($authLine) { return (New-CredentialResult 'missing' "``agy models``: $authLine") }
3251:        $first = if ($allLines.Count -gt 0) { $allLines[-1] } else { 'no output' }
3252:        return (New-CredentialResult 'unknown' "``agy models`` exit $($p.ExitCode) without a model list ($first)")
3253:    } finally {
3254:        $p.Dispose()
3255:    }
3256:}
