3258:# Sign-in of an engine for the preflight and the listing. A missing launcher is always
3259:# missing ("agy CLI not found on PATH"). Then (wave 18, F13) the ledger short-circuit: when
3260:# $Health (Get-EndpointHealth of the engine's endpoint, read from THIS repository's ledgers)
3261:# holds a usable reply no older than 60 minutes (RecentUsable, consult clock), the sign-in is
3262:# evidenced - "ok: signed in (usable reply <m> min ago)" - and nothing is started (also with
3263:# -NoNetwork: it is a ledger read). The caller keeps the endpoint health's auth and quota rules
3264:# in front of it (Get-PreflightVerdict): a recorded auth failure or a usage limit still
3265:# refuses. -NoNetwork (the SessionStart hook): otherwise nothing is started - "not checked
3266:# (launcher present; run codex-providers.ps1)", State unknown, Reason "sign-in not checked" -
3267:# unless the engine's check reads local files only (LocalSignIn: muse's auth.json key names).
3268:# Else the adapter's check (agy: `agy models`, 45 s - TEST HOOK
3269:# CODEX_CONSULT_TEST_LOGIN_TIMEOUT=<s> shortens it). $LoginCache: one check per launcher per
3270:# listing.
3271:function Get-EngineCredential {
3272:    param([string]$Engine, [string]$Launcher, [hashtable]$LoginCache = $null, [switch]$NoNetwork, [int]$TimeoutSec = 0, $Health = $null)
3273:    $spec = Get-EngineSpec -Name $Engine
3274:    if (-not $spec -or -not $spec.Adapter) { return (New-CredentialResult 'unknown' "no credential check for engine '$Engine'") }
3275:    if (-not $Launcher) { return (New-CredentialResult 'missing' "$($spec.Command) CLI not found on PATH") }
3276:    if ($Health -and $Health.PSObject.Properties['RecentUsable'] -and $Health.RecentUsable) {
3277:        return (New-CredentialResult 'ok' "signed in (usable reply $($Health.RecentUsable.AgeMinutes) min ago)")
3278:    }
3279:    if ($NoNetwork -and -not ($spec.PSObject.Properties['LocalSignIn'] -and $spec.LocalSignIn)) { return [pscustomobject]@{ State = 'unknown'; Reason = 'sign-in not checked'; Detail = 'not checked (launcher present; run codex-providers.ps1)' } }
3280:    if ($TimeoutSec -le 0) {
3281:        $TimeoutSec = $script:AgyModelsTimeoutSec
3282:        $hook = ([string]$env:CODEX_CONSULT_TEST_LOGIN_TIMEOUT).Trim()
3283:        if ($hook -match '^[0-9]+$' -and [int]$hook -gt 0) { $TimeoutSec = [int]$hook }
3284:    }
3285:    $key = "engine:$Engine|$Launcher"
3286:    if ($LoginCache -and $LoginCache.ContainsKey($key)) { return $LoginCache[$key] }
3287:    $r = & $spec.Adapter.Credential -Launcher $Launcher -TimeoutSec $TimeoutSec
3288:    if ($LoginCache) { $LoginCache[$key] = $r }
3289:    return $r
3290:}
