3610:
3611:# ---- muse adapter (wave 23: Meta's Muse Code CLI, headless `muse exec`; decisions D1-D16)
3612:
3613:# The Muse sign-in (D5). With TBH_CREDENTIAL_BACKEND=file the CLI keeps it in
3614:# ~/.config/muse/auth.json (home: USERPROFILE on Windows, else HOME); any other backend is the OS
3615:# keychain, which the bridge cannot read (on Windows the keychain write fails anyway: the file
3616:# backend is required there). The file is read for the presence of providers.meta and its
3617:# `mechanism` value only (an enum such as oauth, never a secret); the parsed object is never
3618:# logged, returned or written, and a parse error is reported without its text. Cached per
3619:# backend and path for this process. { Backend (file | keychain); State (ok | missing |
3620:# unknown); Reason; Mechanism ('' when not read; 'unrecognized' for a value that is not a short
3621:# identifier - never shown) }.
3622:$script:MuseCredentialCache = @{}
3623:$script:MuseAuthShown = '~/.config/muse/auth.json'
3624:function Get-MuseAuthPath {
3625:    $h = ''
3626:    if ($script:OnWindows) { $h = [string]$env:USERPROFILE }
3627:    if (-not $h) { $h = [string]$env:HOME }
3628:    if (-not $h) { $h = [string]$HOME }
3629:    if (-not $h) { return '' }
3630:    return (Join-Path (Join-Path (Join-Path $h '.config') 'muse') 'auth.json')
3631:}
3632:function Get-MuseCredentialInfo {
3633:    $backend = ([string]$env:TBH_CREDENTIAL_BACKEND).Trim().ToLowerInvariant()
3634:    $path = Get-MuseAuthPath
3635:    $key = "$backend|$path"
3636:    if ($script:MuseCredentialCache.ContainsKey($key)) { return $script:MuseCredentialCache[$key] }
3637:    $info = [pscustomobject]@{ Backend = $(if ($backend -eq 'file') { 'file' } else { 'keychain' }); State = 'unknown'; Reason = ''; Mechanism = '' }
3638:    $shown = $script:MuseAuthShown
3639:    if ($backend -ne 'file') {
3640:        $info.Reason = "sign-in not checkable: TBH_CREDENTIAL_BACKEND is $(if ($backend) { "'$backend'" } else { 'not set' }) (the keychain backend cannot be read; set TBH_CREDENTIAL_BACKEND=file - required on Windows - and run ``muse login``)"
3641:    } elseif (-not $path) {
3642:        $info.Reason = 'sign-in not checkable: no home directory (USERPROFILE / HOME)'
3643:    } elseif (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
3644:        $info.State = 'missing'
3645:        $info.Reason = "not signed in: $shown does not exist (run ``muse login`` with TBH_CREDENTIAL_BACKEND=file)"
3646:    } else {
3647:        $data = $null
3648:        $why = ''
3649:        $text = Read-SharedText -Path $path
3650:        if (-not $text -or -not $text.Trim()) { $why = 'is empty or could not be read' }
3651:        else {
3652:            try { $data = ConvertFrom-Json -InputObject $text } catch { $why = 'does not parse as JSON' }
3653:            if (-not $why -and -not (Test-IsJsonObject $data)) { $why = 'is not a JSON object' }
3654:        }
3655:        $text = $null
3656:        if ($why) { $info.Reason = "sign-in not checkable: $shown $why" }
3657:        else {
3658:            $providers = Get-PropertyValue $data 'providers' $null
3659:            $meta = $null
3660:            if (Test-IsJsonObject $providers) { $meta = Get-PropertyValue $providers 'meta' $null }
3661:            if (-not (Test-IsJsonObject $meta)) {
3662:                $info.State = 'missing'
3663:                $info.Reason = "not signed in: $shown has no Meta sign-in (providers.meta; run ``muse login``)"
3664:            } else {
3665:                $mech = Get-PropertyValue $meta 'mechanism' $null
3666:                if (-not ($mech -is [string]) -or -not $mech.Trim()) { $info.Reason = "sign-in not checkable: providers.meta in $shown names no mechanism" }
3667:                else {
3668:                    $info.State = 'ok'
3669:                    if ($mech -cmatch '^[A-Za-z][A-Za-z0-9_.-]{0,31}$') { $info.Mechanism = $mech } else { $info.Mechanism = 'unrecognized' }
3670:                    $info.Reason = "signed in ($shown`: providers.meta, mechanism $($info.Mechanism))"
3671:                }
3672:            }
3673:        }
3674:        $data = $null
3675:    }
3676:    $script:MuseCredentialCache[$key] = $info
3677:    return $info
3678:}
3679:
3680:# The preflight's sign-in check of a muse entry (the adapter's Credential; local, nothing is
3681:# started): ok (providers.meta with a mechanism), missing (no file, no providers.meta), unknown
3682:# (the keychain backend, a file that does not parse, no mechanism) - unknown refuses the run
3683:# unless -SkipPreflight (Get-PreflightVerdict).
3684:function Get-MuseSignIn {
3685:    param([string]$Launcher = '', [int]$TimeoutSec = 0)
3686:    $c = Get-MuseCredentialInfo
3687:    return (New-CredentialResult $c.State $c.Reason)
3688:}
