3690:# reviewer.provider_config's muse fields (D4): credential_mechanism = providers.meta.mechanism
3691:# (the file backend), $null when it cannot be read.
3692:function Get-MuseIdentityConfig {
3693:    $c = Get-MuseCredentialInfo
3694:    $o = [ordered]@{}
3695:    $o['credential_mechanism'] = $(if ($c.Mechanism) { $c.Mechanism } else { $null })
