3698:
3699:# The billing invariant of a muse launch (D4): the subscription bills through the browser
3700:# sign-in only; an API key the child would inherit bills per token instead. '' or the refusal:
3701:# META_API_KEY or MODEL_API_KEY set (non-empty) in this process, or a readable credential
3702:# mechanism other than oauth. Names only - a value is never shown. Not a preflight check:
3703:# -SkipPreflight never bypasses it; there is no roster opt-out in this wave.
3704:$script:MuseApiKeyVariables = @('META_API_KEY', 'MODEL_API_KEY')
3705:function Get-MuseLaunchBlock {
3706:    foreach ($name in $script:MuseApiKeyVariables) {
3707:        $v = [Environment]::GetEnvironmentVariable($name)
3708:        if ($v -and $v.Trim()) { return "$name is set: a muse run would bill per token instead of the Muse Code subscription; unset it (the muse process would inherit it)" }
3709:    }
3710:    $c = Get-MuseCredentialInfo
3711:    if ($c.Mechanism -and $c.Mechanism -ne 'oauth') { return "the Muse sign-in in $($script:MuseAuthShown) uses mechanism '$($c.Mechanism)', not oauth: a muse run would not bill the Muse Code subscription; sign in with ``muse login``" }
3712:    return ''
3713:}
3714:
3715:# reviewer.harness of a muse run (D8): "muse-cli <version>" from .muse-version next to the
3716:# launcher (the vendor's install directory), else the `version` of .muse-release-info.json
3717:# there, else `<launcher> --version` (local, no prompt spent; 15 s), else "muse-cli (version
3718:# unknown)". An unseen version is recorded, never refused. Cached per launcher.
3719:$script:MuseHarnessCache = @{}
3720:$script:MuseVersionRe = '^v?[0-9]+\.[0-9]+[0-9A-Za-z.+_-]{0,48}$'
3721:function Get-MuseHarness {
3722:    param([string]$Launcher)
3723:    if (-not $Launcher) { return 'muse-cli (version unknown)' }
3724:    if ($script:MuseHarnessCache.ContainsKey($Launcher)) { return $script:MuseHarnessCache[$Launcher] }
3725:    $ver = ''
3726:    $dir = Split-Path -Parent $Launcher
3727:    if ($dir) {
3728:        $vf = Join-Path $dir '.muse-version'
3729:        if (Test-Path -LiteralPath $vf -PathType Leaf) { $ver = [string](@((Read-SharedText -Path $vf) -split "`r?`n")[0]).Trim() }
3730:        if ($ver -notmatch $script:MuseVersionRe) {
3731:            $ver = ''
3732:            $rf = Join-Path $dir '.muse-release-info.json'
3733:            if (Test-Path -LiteralPath $rf -PathType Leaf) {
3734:                try { $ver = ([string](Get-PropertyValue (ConvertFrom-Json -InputObject (Read-SharedText -Path $rf)) 'version' '')).Trim() } catch { $ver = '' }
3735:            }
3736:        }
3737:    }
3738:    if ($ver -notmatch $script:MuseVersionRe) {
3739:        $ver = ''
3740:        $cap = Invoke-LauncherCapture -Launcher $Launcher -Arguments '--version' -TimeoutSec 15
3741:        if ($cap.Started -and -not $cap.TimedOut -and $cap.Exit -eq 0) {
3742:            foreach ($tok in @(($cap.Out + "`n" + $cap.Err) -split '\s+')) {
3743:                if ($tok -match $script:MuseVersionRe) { $ver = $tok; break }
3744:            }
3745:        }
3746:    }
3747:    $h = $(if ($ver) { "muse-cli $($ver -replace '^v', '')" } else { 'muse-cli (version unknown)' })
3748:    $script:MuseHarnessCache[$Launcher] = $h
3749:    return $h
3750:}
