3752:# The argv of one muse turn (after the launcher), from the turn options: the prompt through
3753:# --prompt-file (the turn's own file; stdin stays empty), the schema through --output-schema
3754:# (structured mode with transport native, and the repair turn), --reasoning-effort only when
3755:# an effort is sent, the read-only flags always, --max-model-steps only with -MaxModelSteps,
3756:# --session-id to continue a session (resume, the format repair).
3757:function New-MuseArgv {
3758:    param($Turn)
3759:    $a = @('exec', '--json', '--prompt-file', [string]$Turn.PromptFile)
3760:    if ($Turn.Schema) { $a += @('--output-schema', [string]$Turn.Schema) }
3761:    $a += @('--model', [string]$Turn.Model)
3762:    if ($null -ne $Turn.Effort -and ([string]$Turn.Effort).Trim()) { $a += @('--reasoning-effort', [string]$Turn.Effort) }
3763:    $a += @('--no-foreign-personal-context', '--disable-web-tools', '--disable-write', '--disable-shell', '--approval-mode', 'never')
3764:    if ([int]$Turn.MaxSteps -gt 0) { $a += @('--max-model-steps', [string][int]$Turn.MaxSteps) }
3765:    if ($Turn.Thread) { $a += @('--session-id', [string]$Turn.Thread) }
3766:    return , ([string[]]$a)
3767:}
