3774:
3775:# One muse stream (stdout of `muse exec --json`: MSP JSONL records {schema_version, id,
3776:# stream{kind,id}, sequence, record_type, payload_type, payload, ...}), parsed into the
3777:# normalized turn record (D6):
3778:#   Records          the records read
3779:#   Malformed        '' or why the stream is malformed: a line that is not a JSON object (the
3780:#                    LAST line may be partial only with -AllowPartialLast, as for agy), a record
3781:#                    without an integer schema_version, a schema_version other than 1
3782:#                    ("unsupported MSP version N"), more than one session stream id, more than one
3783:#                    run_terminal record, a run_terminal record off the session stream
3784:#   SchemaVersion    the first record's schema_version ($null when none) - ledger
3785:#                    engine_run.msp_schema_version
3786:#   Sessions         the distinct stream ids of stream.kind "session" (exactly one expected)

3785:#                    engine_run.msp_schema_version
3786:#   Sessions         the distinct stream ids of stream.kind "session" (exactly one expected)
3787:#   Session / Thread the session id when exactly one ('' otherwise)
3788:#   TerminalCount, HasTerminal, Terminal (payload.terminal: completed | failed | cancelled ...),
3789:#   Text (payload.text), Reason (payload.reason, '' when null)
3790:#   Models           the model_id of every run.model.configured record, in order
3791:#   Error            the reason of a terminal other than completed
3792:#   Usage            $null (MSP records carry no token usage); ToolName, DeniedAction '' (the
3793:#                    run block's shared fields)
3794:function Read-MuseEvents {
3795:    param([string]$Path, [switch]$AllowPartialLast)
3796:    $r = [pscustomobject]@{ Records = 0; Malformed = ''; SchemaVersion = $null; Sessions = [string[]]@(); Session = ''; Thread = ''; TerminalCount = 0; HasTerminal = $false; Terminal = ''; Text = ''; Reason = ''; Models = [string[]]@(); Error = ''; Usage = $null; ToolName = ''; DeniedAction = '' }
3797:    $text = Read-SharedText -Path $Path
3798:    if (-not $text) { return $r }
3799:    $lines = @($text -split "`r?`n")
3800:    $lastIdx = -1
3801:    for ($i = $lines.Count - 1; $i -ge 0; $i--) { if ($lines[$i].Trim()) { $lastIdx = $i; break } }
3802:    $sessions = New-Object System.Collections.Generic.List[string]
3803:    $models = New-Object System.Collections.Generic.List[string]
3804:    $terminal = $null
3805:    $terminalStream = $null
3806:    for ($i = 0; $i -lt $lines.Count; $i++) {
3807:        $t = $lines[$i].Trim()
3808:        if (-not $t) { continue }
3809:        $obj = $null
3810:        try { $obj = ConvertFrom-Json -InputObject $t } catch { $obj = $null }
3811:        if ($null -eq $obj -or -not ($obj -is [System.Management.Automation.PSCustomObject])) {
3812:            if (($i -ne $lastIdx -or -not $AllowPartialLast) -and -not $r.Malformed) { $r.Malformed = "line $($i + 1) is not a JSON object" }
3813:            continue
3814:        }
3815:        $r.Records++
3816:        $sv = Get-PropertyValue $obj 'schema_version' $null
3817:        if (-not (Test-IsJsonInteger $sv)) {
3818:            if (-not $r.Malformed) { $r.Malformed = "the record at line $($i + 1) has no integer schema_version" }
3819:        } else {
3820:            if ($null -eq $r.SchemaVersion) { $r.SchemaVersion = [int]$sv }
3821:            if ([long]$sv -ne 1 -and -not $r.Malformed) { $r.Malformed = "unsupported MSP version $sv (the bridge reads MSP 1)" }
3822:        }
3823:        $stream = Get-PropertyValue $obj 'stream' $null
3824:        $sKind = ''
3825:        $sId = ''
3826:        if (Test-IsJsonObject $stream) {
3827:            $sKind = [string](Get-PropertyValue $stream 'kind' '')
3828:            $sId = [string](Get-PropertyValue $stream 'id' '')
3829:        }
3830:        if ($sKind -eq 'session' -and $sId -and -not $sessions.Contains($sId)) { $sessions.Add($sId) }
3831:        $pType = [string](Get-PropertyValue $obj 'payload_type' '')
3832:        $payload = Get-PropertyValue $obj 'payload' $null
3833:        $pKind = ''
3834:        if (Test-IsJsonObject $payload) { $pKind = [string](Get-PropertyValue $payload 'kind' '') }
3835:        if ($pType -eq 'run.model.configured' -or $pKind -eq 'run_model_configured') {
3836:            $mid = [string](Get-PropertyValue $payload 'model_id' '')
3837:            if ($mid) { $models.Add($mid) }
3838:        }
3839:        if ($pKind -eq 'run_terminal' -or $pType -like 'run.terminal.*') {
3840:            $r.TerminalCount++
3841:            $terminal = $payload
3842:            $terminalStream = [pscustomobject]@{ Kind = $sKind; Id = $sId; Line = $i + 1 }
3843:        }
3844:    }
3845:    $r.Sessions = [string[]]$sessions.ToArray()
3846:    $r.Models = [string[]]$models.ToArray()
3847:    if ($sessions.Count -gt 1 -and -not $r.Malformed) { $r.Malformed = "$($sessions.Count) session streams (exactly one expected): $($sessions.ToArray() -join ', ')" }
3848:    if ($r.TerminalCount -gt 1 -and -not $r.Malformed) { $r.Malformed = "$($r.TerminalCount) run_terminal records (exactly one expected)" }
3849:    if ($sessions.Count -eq 1) { $r.Session = $sessions[0]; $r.Thread = $sessions[0] }
3850:    if ($null -ne $terminal) {
3851:        $r.HasTerminal = $true
3852:        if (Test-IsJsonObject $terminal) {
3853:            $r.Terminal = [string](Get-PropertyValue $terminal 'terminal' '')
3854:            $tx = Get-PropertyValue $terminal 'text' $null
3855:            if ($null -eq $tx) { $r.Text = '' } elseif ($tx -is [string]) { $r.Text = $tx } else { $r.Text = ConvertTo-Json -InputObject $tx -Compress -Depth 30 }
3856:            $rs = Get-PropertyValue $terminal 'reason' $null
3857:            if ($null -eq $rs) { $r.Reason = '' } elseif ($rs -is [string]) { $r.Reason = $rs } else { $r.Reason = ConvertTo-Json -InputObject $rs -Compress -Depth 10 }
3858:        } elseif (-not $r.Malformed) { $r.Malformed = "the run_terminal record at line $($terminalStream.Line) has no payload object" }
3859:        if (-not $r.Malformed -and ($terminalStream.Kind -ne 'session' -or ($r.Session -and $terminalStream.Id -ne $r.Session))) {
3860:            $r.Malformed = "the run_terminal record at line $($terminalStream.Line) is on stream $(if ($terminalStream.Kind) { $terminalStream.Kind } else { '(none)' }) $($terminalStream.Id), not on the session stream"
3861:        }
3862:        if ($r.Terminal -ne 'completed') { $r.Error = $r.Reason }
3863:    }
3864:    return $r
3865:}
3866:
3867:# The failure rules of one muse turn (the main turn, the format repair; D6, D7). The same result
3868:# object as Get-AgyTurnOutcome (DeniedEmpty is always $false: there is no denial retry):
3869:#   $Pre             a failure the bridge already knows (its own timeout, could not start) wins
3870:#   (detail: the terminal's reason, else the first `error:` line of stderr, else its last line)
3871:#   exit 2           failed: muse exit 2 (usage error) - <detail>, class capability
3872:#   exit 130 / 143   failed: muse exit <n> (stopped by a signal) - <detail>, class transport
3873:#   other exit != 0  failed: muse exit <n> - <terminal reason | stderr>; a reason that names the
3874:#                    step cap -> "max model steps reached", class capability; else the texts'
3875:#                    classifier (quota wording -> quota, with retry_after when a reset is named)
3876:#   malformed        failed: malformed event stream: <why>, class transport
3877:#   no terminal      failed: no run_terminal record in the muse event stream, classified text
3878:#   no session       failed (class unknown)
3879:#   $ExpectThread    (resume, repair) a session other than the requested one -> failed: parent
3880:#                    session <p> not found, muse started <s> (class unknown; a candidate only)
3881:#   terminal != completed  failed: muse terminal <t> - <reason> (step cap: capability)
3882:#   session not a uuid     failed (class unknown)
3883:#   $ExpectModel     run.model.configured must name exactly the requested model: none -> failed
3884:#                    (class unknown), another -> failed: model drift: asked X, served Y (class
3885:#                    capability); the session is then a candidate only, never a parent
3886:#   empty text       failed: empty reply
3887:#   usable           every `warning:` line of stderr becomes a Warning
3888:$script:MuseStepCapRe = '(?i)\bmax(?:imum)?[ _-]?(?:model[ _-]?)?steps?\b|\bstep (?:cap|limit|budget)\b'
3889:# The informational lines every `muse exec` prints on stderr (the workspace root; "Agent
3890:# delegation: auto unavailable: workspace is untrusted.") - never a failure's detail (the second
3891:# would read as class transport).
3892:$script:MuseInfoStderrRe = '(?i)^muse:\s*(workspace root:|agent delegation:)'
3893:function Get-MuseTurnOutcome {
3894:    param($Events, [int]$ExitCode, [string]$StderrText = '', [string]$Pre = '', [string]$ExpectThread = '', [string]$ExpectModel = '')
3895:    $o = [pscustomobject]@{ Ok = $false; Outcome = ''; Class = ''; Texts = [string[]]@(); Thread = ''; ThreadCandidate = ''; Reply = ''; Structured = $false; DeniedEmpty = $false; DenialLine = ''; Permission = ''; NotFound = ''; Warnings = [string[]]@() }
3896:    $lines = @(([string]$StderrText) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ -and $_ -notmatch $script:MuseInfoStderrRe })
3897:    $warnLines = @($lines | Where-Object { $_ -match '(?i)^(muse:\s*)?warning:' })
3898:    # the telling stderr line: the first `error:` line (a usage error ends with its usage
3899:    # boilerplate), else the last line
3900:    $errLine = @($lines | Where-Object { $_ -match '(?i)^(muse:\s*)?error\b' }) | Select-Object -First 1
3901:    $stderrTail = if ($errLine) { [string]$errLine } elseif ($lines.Count -gt 0) { $lines[-1] } else { '' }
3902:    $session = [string]$Events.Session
3903:    $isUuid = ($session -match $script:UuidRe)
3904:    if ($Events.Terminal -eq 'completed') { $o.Reply = [string]$Events.Text }
3905:    if ($o.Reply.Trim().StartsWith('{')) { try { $o.Structured = (Test-IsJsonObject (ConvertFrom-Json -InputObject $o.Reply)) } catch { $o.Structured = $false } }
3906:    $reason = [string]$Events.Reason
3907:    $detail = if ($reason) { $reason } else { $stderrTail }
3908:    $stepCap = ($detail -and $detail -match $script:MuseStepCapRe)
3909:    $fail = {
3910:        param([string]$Why, [string]$Class = '', [string[]]$Texts = @())
3911:        $o.Ok = $false
3912:        $o.Outcome = "failed: $Why"
3913:        $o.Class = $Class
3914:        $o.Texts = [string[]]@(@($Texts) + @($Why) | Where-Object { $_ })
3915:    }
3916:    if ($Pre) {
3917:        $o.Outcome = $Pre
3918:        $o.Texts = [string[]]@(@($reason, $detail, ($Pre -replace '^failed:\s*', '')) | Where-Object { $_ })
3919:        if ($isUuid) { $o.ThreadCandidate = $session }
3920:        return $o
3921:    }
3922:    if ($ExitCode -ne 0) {
3923:        $tail = $(if ($detail) { " - $(ConvertTo-OneLine $detail)" } else { '' })
3924:        if ($ExitCode -eq 2) { & $fail "muse exit 2 (usage error)$tail" 'capability' @($detail) }
3925:        elseif ($ExitCode -eq 130 -or $ExitCode -eq 143) { & $fail "muse exit $ExitCode (stopped by a signal)$tail" 'transport' @($detail) }
3926:        elseif ($stepCap) { & $fail "muse exit $ExitCode - max model steps reached$(if ($detail) { " ($(ConvertTo-OneLine $detail))" })" 'capability' @($detail) }
3927:        else { & $fail "muse exit $ExitCode$tail" '' @($reason, $stderrTail) }
3928:        if ($isUuid -and (-not $ExpectThread -or $session -eq $ExpectThread)) { $o.Thread = $session } elseif ($isUuid) { $o.ThreadCandidate = $session }
3929:        return $o
3930:    }
3931:    if ($Events.Malformed) {
3932:        & $fail "malformed event stream: $($Events.Malformed)" 'transport'
3933:        if ($isUuid) { $o.ThreadCandidate = $session }
3934:        return $o
3935:    }
3936:    if (-not $Events.HasTerminal) {
3937:        & $fail "no run_terminal record in the muse event stream$(if ($stderrTail) { " - $(ConvertTo-OneLine $stderrTail)" })" '' @($stderrTail)
3938:        if ($isUuid) { $o.ThreadCandidate = $session }
3939:        return $o
3940:    }
3941:    if (-not $session) {
3942:        & $fail 'the muse event stream names no session (no stream of kind session)' 'unknown'
3943:        return $o
3944:    }
3945:    if ($ExpectThread -and $session -ne $ExpectThread) {
3946:        & $fail "parent session $ExpectThread not found, muse started $session" 'unknown'
3947:        if ($isUuid) { $o.ThreadCandidate = $session }
3948:        return $o
3949:    }
3950:    if ($Events.Terminal -ne 'completed') {
3951:        $t = if ($Events.Terminal) { $Events.Terminal } else { '(none)' }
3952:        if ($stepCap) { & $fail "muse terminal $t - max model steps reached$(if ($detail) { " ($(ConvertTo-OneLine $detail))" })" 'capability' @($detail) }
3953:        else { & $fail "muse terminal $t$(if ($detail) { " - $(ConvertTo-OneLine $detail)" })" '' @($reason, $stderrTail) }
3954:        if ($isUuid) { $o.Thread = $session }
3955:        return $o
3956:    }
3957:    if (-not $isUuid) {
3958:        & $fail "the session id '$session' is not a uuid" 'unknown'
3959:        return $o
3960:    }
3961:    if ($ExpectModel) {
3962:        $served = @($Events.Models)
3963:        if ($served.Count -eq 0) {
3964:            & $fail "the muse event stream names no configured model (run.model.configured; asked $ExpectModel)" 'unknown'
3965:            $o.ThreadCandidate = $session
3966:            return $o
3967:        }
3968:        $other = @($served | Where-Object { $_ -cne $ExpectModel }) | Select-Object -First 1
3969:        if ($other) {
3970:            & $fail "model drift: asked $ExpectModel, served $other" 'capability'
3971:            $o.ThreadCandidate = $session
3972:            return $o
3973:        }
3974:    }
3975:    $o.Thread = $session
3976:    if (-not $o.Reply.Trim()) {
3977:        & $fail 'empty reply' ''
3978:        return $o
3979:    }
3980:    $o.Ok = $true
3981:    $o.Outcome = 'usable reply'
3982:    $o.Warnings = [string[]]@($warnLines | ForEach-Object { ConvertTo-OneLine $_ })
3983:    return $o
3984:}
3985:
3986:# Classes of a provider failure, tried in this order (case-insensitive). permission comes
3987:# first (0.4.0, agy F11: a tool the headless print mode cannot grant was auto-denied and
3988:# the turn produced nothing). capability comes next: "Your token plan does not support
3989:# response_format" is a capability rejection, not a quota one. auth matches whole words
3990:# only ("text authored by" is not auth). transport stays last. Google's wordings (the agy
3991:# engine): RESOURCE_EXHAUSTED -> quota, UNAUTHENTICATED / PERMISSION_DENIED / "not signed
3992:# in" -> auth, INVALID_ARGUMENT / "invalid model selection" -> capability, UNAVAILABLE /
3993:# DEADLINE_EXCEEDED -> transport.
3994:# A usage limit said in WORDS ($script:QuotaTextPattern: usage limit, quota, rate limit, ...)
3995:# is quota even under an auth status, and is tried right before auth: Kimi Code answers "403
3996:# Forbidden: You've reached your 5-hour usage limit..." (live ledger, 2026-09-26), which the
3997:# 403 must not turn into an auth failure - the preflight would refuse that endpoint for 24 h.
3998:$script:QuotaTextPattern = '(?i)usage[ _]limit|quota|rate[ _]limit|resource_exhausted|too many requests'
3999:$script:FailureClassPatterns = [ordered]@{
4000:    'permission' = '(?i)no output produced|auto-denied|permission that headless mode'
4001:    'capability' = '(?i)not supported|unsupported|does(?: not|n[''\u2019]t) support|do not support|feature_not_supported|json_schema|invalid_argument|invalid model selection|conflicts with --effort'
4002:    'auth'       = '(?i)\b40[13]\b|unauthori[sz]ed|forbidden|invalid[ _]api[ _]key|\bauthentication\b|\bauth\b|\bapi key\b|permission_denied|unauthenticated|not signed in|login required|sign in to'
4003:    'quota'      = '(?i)usage[ _]limit|quota|rate[ _]limit|\b429\b|insufficient balance|too many requests|credits? exhausted|credit balance|payment required|\b402\b|token plan|plan exhausted|billing|resource_exhausted|rate_limit_exceeded'
4004:    'transport'  = '(?i)timeout|timed out|connection|econn|enotfound|\bdns\b|\btls\b|certificate|\b50[234]\b|network|\bunavailable\b|deadline_exceeded'
4005:}
4006:$script:BuiltinOpenAiFingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes('cc-provider-v1|builtin:openai'))
4007:
4008:# permission | capability | auth | quota | transport | unknown
4009:function Get-ProviderFailureClass {
4010:    param([string]$Message)
4011:    foreach ($k in $script:FailureClassPatterns.Keys) {
4012:        if ($k -eq 'auth' -and $Message -match $script:QuotaTextPattern) { return 'quota' }
4013:        if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
4014:    }
4015:    return 'unknown'
4016:}
