4018:# The provider's own error inside a failure text: an SSE payload `data:{"error":{...}}`
4019:# (MiMo sends its rejections that way) or a bare `{"error":{...}}` -> error.message and

4009:function Get-ProviderFailureClass {
4010:    param([string]$Message)
4011:    foreach ($k in $script:FailureClassPatterns.Keys) {
4012:        if ($k -eq 'auth' -and $Message -match $script:QuotaTextPattern) { return 'quota' }
4013:        if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
4014:    }
4015:    return 'unknown'
4016:}
4017:
4018:# The provider's own error inside a failure text: an SSE payload `data:{"error":{...}}`
4019:# (MiMo sends its rejections that way) or a bare `{"error":{...}}` -> error.message and
4020:# error.code; otherwise the text itself. { Code; Message }.
4021:function ConvertFrom-ProviderErrorText {
4022:    param([string]$Text)
4023:    $r = [pscustomobject]@{ Code = ''; Message = (ConvertTo-OneLine $Text) }
4024:    if (-not $Text) { return $r }
4025:    $candidates = New-Object System.Collections.Generic.List[string]
4026:    foreach ($m in [regex]::Matches($Text, '(?m)data:\s*(\{.*\})\s*$')) { $candidates.Add($m.Groups[1].Value) }
4027:    $at = $Text.IndexOf('{"error"')
4028:    if ($at -ge 0) { $candidates.Add($Text.Substring($at).Trim()) }
4029:    foreach ($json in $candidates) {
4030:        $o = $null
4031:        try { $o = ConvertFrom-Json -InputObject $json } catch { continue }
4032:        $e = Get-PropertyValue $o 'error' $null
4033:        if ($null -eq $e) { continue }
4034:        if ($e -is [string]) { $r.Message = ConvertTo-OneLine $e; return $r }
4035:        $msg = [string](Get-PropertyValue $e 'message' '')
4036:        if ($msg) { $r.Message = ConvertTo-OneLine $msg }
4037:        $r.Code = [string](Get-PropertyValue $e 'code' '')
4038:        if (-not $r.Code) { $r.Code = [string](Get-PropertyValue $e 'type' '') }
4039:        return $r
4040:    }
4041:    return $r
4042:}
4043:
4044:# When a provider says its limit resets - read from its failure message, never guessed.
4045:# Recognised (case-insensitive; a straight or a curly apostrophe makes no difference):
4046:#   1. Codex's wording "try again at Sep 28th, 2026 8:35 PM." (also "resets at",
4047:#      "available at", "until" before the same form; full or 3-letter month names; the
4048:#      ordinal suffix, the comma, the year and AM/PM are optional - no AM/PM = a 24-hour
4049:#      clock; no year = the reference's year, or the next one when that date lies more
4050:#      than a day before the reference). Codex prints a WALL-CLOCK time of the machine it
4051:#      runs on (ConvertFrom-WallClock).
4052:#   2. an ISO-8601 timestamp after try again / retry / reset / until / available: with an
4053:#      offset it is an instant; without one it is a wall-clock time like 1.
4054:#   3. a duration: "retry after 30" / "Retry-After: 30s" (no unit = seconds), "retry after
4055:#      1 week", "try again in 5 minutes", "resets in 2 days", "try again in 3 days 1 hour
4056:#      7 minutes" (units w, d, h, m, s; the parts are summed) -> $Reference + it.
4057:#   4. Google's wordings (the agy engine, 0.4.0): "retry in 32s", "retry in 1m5.3s" (Go
4058:#      durations: h, m, s, ms, decimals), "retry in 90 seconds", and the gRPC RetryInfo
4059:#      payload "retryDelay":{"seconds":32} / "retryDelay": "32s" / retryDelay: 32s ->
4060:#      $Reference + it, fractions rounded UP to the next second.
4061:#   5. a compact duration after resets / try again / retry / available in (0.4.x, the agy
4062:#      quota "Individual quota reached. ... Resets in 68h58m18s."; also "in 2d3h", "in 45m",
4063:#      "in 30s"; units w, d, h, m, s, ms, decimals) -> $Reference + it, rounded up.
4064:#   6. a rolling window (0.4.x, Kimi Code: "You've reached your 5-hour usage limit. Your quota
4065:#      will reset when the current 5-hour window ends.") -> $Reference + the window's length.
4066:#      That is an UPPER BOUND, not the provider's own reset time: the window ends at the
4067:#      latest one window length after the failure (it began at or before it). Tried last.
4068:# Which offset (F15-1):
4069:#   write time (New-ProviderFailure, on the machine that saw the failure): a wall-clock
4070:#     time is read with the rules of -TimeZone (default [TimeZoneInfo]::Local), so a reset
4071:#     on the far side of a daylight-saving change gets the offset valid THEN (Berlin: a
4072:#     failure at 2026-10-25T01:00+02:00 saying "Oct 26th, 2026 8:35 PM" ->
4073:#     2026-10-26T20:35:00+01:00). A time that does not exist (the spring gap) takes the
4074:#     offset after the transition, an ambiguous one (the autumn overlap) the offset before
4075:#     it. Instants are shown in that zone.
4076:#   read time (-ReferenceOffset: a ledger entry recorded without retry_after): the reader's
4077:#     zone may not be the recorder's, so the offset of $Reference (the failure's `when`) is
4078:#     used for a wall-clock time and for display.
4079:# DateTimeOffset, or $null when the message names no reset time.
4080:$script:MonthNumbers = @{ 'jan' = 1; 'feb' = 2; 'mar' = 3; 'apr' = 4; 'may' = 5; 'jun' = 6; 'jul' = 7; 'aug' = 8; 'sep' = 9; 'oct' = 10; 'nov' = 11; 'dec' = 12 }
4081:$script:DurationUnit = '(?:weeks?|wks?|w|days?|d|hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)\b'
4082:$script:RetryAfterRe = @{
4083:    Codex = [regex]('(?i)(?:try\s+again\s+(?:at|on|after)|resets?\s+(?:at|on)|available\s+(?:again\s+)?(?:at|on|after)|until)\s+' +
4084:        '(?<mon>jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?\s+' +
4085:        '(?<day>[0-9]{1,2})(?:st|nd|rd|th)?\b,?\s*(?:(?<year>[0-9]{4})\b,?\s*)?(?:at\s+)?' +
4086:        '(?<hour>[0-9]{1,2}):(?<min>[0-9]{2})(?::(?<sec>[0-9]{2}))?(?:\s*(?<ampm>[ap])\.?\s?m\b\.?)?')
4087:    Iso   = [regex]'(?i)(?:try\s+again|retry|resets?|until|available)[^0-9\r\n]{0,24}?(?<date>[0-9]{4}-[0-9]{2}-[0-9]{2})[T ](?<time>[0-9]{2}:[0-9]{2}(?::[0-9]{2}(?:\.[0-9]+)?)?)(?<tz>Z|[+-][0-9]{2}:?[0-9]{2})?'
4088:    After = [regex]('(?i)retry[- ]after[:\s]\s*(?<n>[0-9]+)(?![0-9:.\-])(?:\s*(?<u>' + $script:DurationUnit + '))?')
4089:    In    = [regex]('(?i)(?:try\s+again|resets?)\s+in\s+(?<parts>[0-9]+\s*' + $script:DurationUnit + '(?:(?:\s*,\s*|\s+and\s+|\s+)[0-9]+\s*' + $script:DurationUnit + ')*)')
4090:    Part  = [regex]('(?i)(?<n>[0-9]+)\s*(?<u>' + $script:DurationUnit + ')')
4091:    # Google: "retry in 32s" / "retry in 1m5.3s" (a Go duration) / "retry in 90 seconds"
4092:    RetryIn = [regex]'(?i)\bretry\s+in\s+(?<dur>(?:[0-9]+(?:\.[0-9]+)?(?:ms|h|m|s))+(?![A-Za-z0-9])|[0-9]+(?:\.[0-9]+)?\s*(?:hours?|hrs?|minutes?|mins?|seconds?|secs?)\b(?:(?:\s*,\s*|\s+and\s+|\s+)[0-9]+(?:\.[0-9]+)?\s*(?:hours?|hrs?|minutes?|mins?|seconds?|secs?)\b)*)'
4093:    # gRPC RetryInfo: "retryDelay":{"seconds":32} or "retryDelay": "32s" / retryDelay: 32s
4094:    RetryDelay = [regex]'(?i)retryDelay"?\s*[:=]\s*(?:\{\s*"?seconds"?\s*:\s*"?(?<sec>[0-9]+)|"?(?<dur>(?:[0-9]+(?:\.[0-9]+)?(?:ms|h|m|s))+)(?![A-Za-z0-9]))'
4095:    GoPart = [regex]'(?i)(?<n>[0-9]+(?:\.[0-9]+)?)\s*(?<u>ms|hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)'
4096:    # a compact duration: "Resets in 68h58m18s", "in 2d3h", "in 45m", "in 30s"
4097:    Compact = [regex]'(?i)\b(?:try\s+again|resets?|retry|available(?:\s+again)?)\s+in\s+(?<dur>(?:[0-9]+(?:\.[0-9]+)?(?:w|d|h|ms|m|s))+)(?![A-Za-z0-9])'
4098:    CompactPart = [regex]'(?i)(?<n>[0-9]+(?:\.[0-9]+)?)(?<u>w|d|h|ms|m|s)'
4099:    # a rolling window: "reset when the current 5-hour window ends" (an UPPER BOUND)
4100:    Window = [regex]'(?i)\bresets?\s+when\s+the\s+current\s+(?<n>[0-9]+)[- ](?<u>minute|hour|day|week)s?\s+window\s+ends'
4101:}
4102:# Seconds of a Go duration ("1m5.3s", "500ms") or a worded one ("90 seconds", "1 hour 30
4103:# minutes"); decimals allowed; $null when nothing parses.
4104:function ConvertFrom-GoDuration {
4105:    param([string]$Text)
4106:    $total = [double]0
4107:    $any = $false
4108:    foreach ($p in $script:RetryAfterRe.GoPart.Matches([string]$Text)) {
4109:        $n = [double]::Parse($p.Groups['n'].Value, $script:Invariant)
4110:        $u = $p.Groups['u'].Value.ToLowerInvariant()
4111:        if ($u -eq 'ms') { $total += $n / 1000 }
4112:        elseif ($u.StartsWith('h')) { $total += $n * 3600 }
4113:        elseif ($u.StartsWith('m')) { $total += $n * 60 }
4114:        else { $total += $n }
4115:        $any = $true
4116:    }
4117:    if (-not $any) { return $null }
4118:    return $total
4119:}
4120:# Seconds of a compact duration ("68h58m18s", "2d3h", "500ms"; units w, d, h, m, s, ms,
4121:# decimals); $null when nothing parses.
4122:function ConvertFrom-CompactDuration {
4123:    param([string]$Text)
4124:    $total = [double]0
4125:    $any = $false
4126:    foreach ($p in $script:RetryAfterRe.CompactPart.Matches([string]$Text)) {
4127:        $n = [double]::Parse($p.Groups['n'].Value, $script:Invariant)
4128:        switch ($p.Groups['u'].Value.ToLowerInvariant()) {
4129:            'w' { $total += $n * 604800 }
4130:            'd' { $total += $n * 86400 }
4131:            'h' { $total += $n * 3600 }
4132:            'm' { $total += $n * 60 }
4133:            'ms' { $total += $n / 1000 }
4134:            default { $total += $n }
4135:        }
4136:        $any = $true
4137:    }
4138:    if (-not $any) { return $null }
4139:    return $total
4140:}
4141:function ConvertTo-DurationSeconds {
4142:    param([long]$N, [string]$Unit)
4143:    $u = ([string]$Unit).ToLowerInvariant()
4144:    if ($u.StartsWith('w')) { return $N * 604800 }
4145:    if ($u.StartsWith('d')) { return $N * 86400 }
4146:    if ($u.StartsWith('h')) { return $N * 3600 }
4147:    if ($u.StartsWith('m')) { return $N * 60 }
4148:    return $N
4149:}
4150:# A wall-clock time -> DateTimeOffset (see Get-RetryAfter): the offset of $TimeZone at that
4151:# time (a nonexistent time: the offset after the transition; an ambiguous one: the offset
4152:# before it), or with -ReferenceOffset (or no zone) the offset of $Reference.
4153:function ConvertFrom-WallClock {
4154:    param([datetime]$Wall, [DateTimeOffset]$Reference, [TimeZoneInfo]$TimeZone = $null, [switch]$ReferenceOffset)
4155:    $w = [datetime]::SpecifyKind($Wall, [DateTimeKind]::Unspecified)
4156:    if ($ReferenceOffset -or $null -eq $TimeZone) { return (New-Object DateTimeOffset -ArgumentList $w, $Reference.Offset) }
4157:    if ($TimeZone.IsInvalidTime($w)) { $offset = $TimeZone.GetUtcOffset($w.AddDays(1)) }
4158:    elseif ($TimeZone.IsAmbiguousTime($w)) { $offset = $TimeZone.GetUtcOffset($w.AddDays(-1)) }
4159:    else { $offset = $TimeZone.GetUtcOffset($w) }
4160:    return (New-Object DateTimeOffset -ArgumentList $w, $offset)
4161:}
4162:
4163:# An instant shown in $TimeZone (or, with -ReferenceOffset / no zone, in $Reference's offset).
4164:function ConvertTo-ZoneTime {
4165:    param([DateTimeOffset]$At, [DateTimeOffset]$Reference, [TimeZoneInfo]$TimeZone = $null, [switch]$ReferenceOffset)
4166:    if ($ReferenceOffset -or $null -eq $TimeZone) { return $At.ToOffset($Reference.Offset) }
4167:    return [TimeZoneInfo]::ConvertTime($At, $TimeZone)
4168:}
4169:
4170:function Get-RetryAfter {
4171:    param([string]$Message, [DateTimeOffset]$Reference, [TimeZoneInfo]$TimeZone = [TimeZoneInfo]::Local, [switch]$ReferenceOffset)
4172:    if (-not $Message) { return $null }
4173:    $text = $Message -replace '[\u2018\u2019]', "'"
4174:    $m = $script:RetryAfterRe.Codex.Match($text)
4175:    if ($m.Success) {
4176:        try {
4177:            $month = $script:MonthNumbers[$m.Groups['mon'].Value.Substring(0, 3).ToLowerInvariant()]
4178:            $day = [int]$m.Groups['day'].Value
4179:            $hour = [int]$m.Groups['hour'].Value
4180:            $minute = [int]$m.Groups['min'].Value
4181:            $second = 0
4182:            if ($m.Groups['sec'].Success) { $second = [int]$m.Groups['sec'].Value }
4183:            $ok = $true
4184:            if ($m.Groups['ampm'].Success) {
4185:                if ($hour -lt 1 -or $hour -gt 12) { $ok = $false }
4186:                $pm = ($m.Groups['ampm'].Value -ieq 'p')
4187:                if ($hour -eq 12) { $hour = 0 }
4188:                if ($pm) { $hour += 12 }
4189:            }
4190:            if ($ok) {
4191:                if ($m.Groups['year'].Success) {
4192:                    $wall = New-Object DateTime -ArgumentList ([int]$m.Groups['year'].Value), $month, $day, $hour, $minute, $second
4193:                    return (ConvertFrom-WallClock -Wall $wall -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset)
4194:                }
4195:                $at = ConvertFrom-WallClock -Wall (New-Object DateTime -ArgumentList $Reference.Year, $month, $day, $hour, $minute, $second) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset
4196:                if ($at -lt $Reference.AddDays(-1)) {
4197:                    $at = ConvertFrom-WallClock -Wall (New-Object DateTime -ArgumentList ($Reference.Year + 1), $month, $day, $hour, $minute, $second) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset
4198:                }
4199:                return $at
4200:            }
4201:        } catch { }
4202:    }
4203:    $m = $script:RetryAfterRe.Iso.Match($text)
4204:    if ($m.Success) {
4205:        $stamp = $m.Groups['date'].Value + 'T' + $m.Groups['time'].Value
4206:        $tz = $m.Groups['tz'].Value
4207:        if ($tz -and $tz -ne 'Z' -and $tz -ne 'z' -and $tz.Length -eq 5) { $tz = $tz.Substring(0, 3) + ':' + $tz.Substring(3) }
4208:        $dto = [DateTimeOffset]::MinValue
4209:        if ($tz) {
4210:            if ([DateTimeOffset]::TryParse($stamp + $tz.ToUpperInvariant(), $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dto)) {
4211:                return (ConvertTo-ZoneTime -At $dto -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset)
4212:            }
4213:        } else {
4214:            $dt = [datetime]::MinValue
4215:            if ([datetime]::TryParse($stamp, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) {
4216:                try { return (ConvertFrom-WallClock -Wall $dt -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset) } catch { }
4217:            }
4218:        }
4219:    }
4220:    $m = $script:RetryAfterRe.After.Match($text)
4221:    if ($m.Success) {
4222:        $unit = if ($m.Groups['u'].Success) { $m.Groups['u'].Value } else { 's' }
4223:        $at = $Reference.AddSeconds((ConvertTo-DurationSeconds -N ([long]$m.Groups['n'].Value) -Unit $unit))
4224:        return (ConvertTo-ZoneTime -At $at -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset)
4225:    }
4226:    $m = $script:RetryAfterRe.In.Match($text)
4227:    if ($m.Success) {
4228:        $total = [long]0
4229:        foreach ($part in $script:RetryAfterRe.Part.Matches($m.Groups['parts'].Value)) {
4230:            $total += (ConvertTo-DurationSeconds -N ([long]$part.Groups['n'].Value) -Unit $part.Groups['u'].Value)
4231:        }
4232:        return (ConvertTo-ZoneTime -At ($Reference.AddSeconds($total)) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset)
4233:    }
4234:    # a compact duration: "Resets in 68h58m18s", "in 2d3h" (5.)
4235:    $m = $script:RetryAfterRe.Compact.Match($text)
4236:    if ($m.Success) {
4237:        $secs = ConvertFrom-CompactDuration -Text $m.Groups['dur'].Value
4238:        if ($null -ne $secs) { return (ConvertTo-ZoneTime -At ($Reference.AddSeconds([Math]::Ceiling($secs))) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset) }
4239:    }
4240:    # Google (agy): "retry in 32s", "retry in 1m5.3s", "retry in 90 seconds"
4241:    $m = $script:RetryAfterRe.RetryIn.Match($text)
4242:    if ($m.Success) {
4243:        $secs = ConvertFrom-GoDuration -Text $m.Groups['dur'].Value
4244:        if ($null -ne $secs) { return (ConvertTo-ZoneTime -At ($Reference.AddSeconds([Math]::Ceiling($secs))) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset) }
4245:    }
4246:    # gRPC RetryInfo: "retryDelay":{"seconds":N} / "retryDelay": "32s"
4247:    $m = $script:RetryAfterRe.RetryDelay.Match($text)
4248:    if ($m.Success) {
4249:        $secs = $null
4250:        if ($m.Groups['sec'].Success) { $secs = [double]$m.Groups['sec'].Value }
4251:        else { $secs = ConvertFrom-GoDuration -Text $m.Groups['dur'].Value }
4252:        if ($null -ne $secs) { return (ConvertTo-ZoneTime -At ($Reference.AddSeconds([Math]::Ceiling($secs))) -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset) }
4253:    }
4254:    # a rolling window (6.): the failure + the window's length - an UPPER BOUND
4255:    $m = $script:RetryAfterRe.Window.Match($text)
4256:    if ($m.Success) {
4257:        $at = $Reference.AddSeconds((ConvertTo-DurationSeconds -N ([long]$m.Groups['n'].Value) -Unit $m.Groups['u'].Value))
4258:        return (ConvertTo-ZoneTime -At $at -Reference $Reference -TimeZone $TimeZone -ReferenceOffset:$ReferenceOffset)
4259:    }
4260:    return $null
4261:}
4262:
4263:function Format-OffsetIso {
4264:    param($Value)
4265:    if ($null -eq $Value) { return '' }
4266:    return ([DateTimeOffset]$Value).ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant)
4267:}
4268:
4269:# The ledger's provider_failure of a failed run: { class; code; message (<= 200); when;
4270:# retry_after }. $Texts: the evidence in order of preference (the event-stream error,
4271:# stderr, the bridge outcome); the first that holds a provider error payload wins, else the
4272:# first non-empty. retry_after: the reset time the chosen message names (Get-RetryAfter,
4273:# read from the FULL message before it is cut to 200 characters), ISO with offset, or $null.
4274:function New-ProviderFailure {
4275:    param([string[]]$Texts, [string]$Class = '')
4276:    $chosen = $null
4277:    $chosenRaw = ''
4278:    foreach ($t in @($Texts | Where-Object { $_ -and $_.Trim() })) {
4279:        $p = ConvertFrom-ProviderErrorText -Text $t

