4347:function Get-EndpointHealth {
4348:    param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
4349:    $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
4350:    if (-not $Fingerprint) { return $h }
4351:    $records = New-Object System.Collections.Generic.List[object]
4352:    foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
4353:        $rev = Get-PropertyValue $c 'reviewer' $null
4354:        $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
4355:        if (-not $fp -or $fp -ne $Fingerprint) { continue }
4356:        $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
4357:        if (-not $outcome) { continue }
4358:        $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
4359:        if ($null -eq $at) { continue }
4360:        # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
4361:        # its age is clamped to 0, it is never skipped (F15-4).
4362:        $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
4363:        # "Newest" is by COMPLETION (D9, F03-3): a panel's members start together and finish in
4364:        # any order, so a member that started later may have succeeded before an earlier one hit
4365:        # its usage limit. finished_at (0.4.x wave 21), else when + wall_seconds (older entries),
4366:        # else when; ties by n (F02-5).
4367:        $order = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
4368:        if ($null -eq $order) {
4369:            $order = $at
4370:            $ws = 0.0
4371:            if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$ws) -and $ws -gt 0) { $order = $at.AddSeconds($ws) }
4372:        }
4373:        $entryN = 0
4374:        [void][int]::TryParse([string](Get-PropertyValue $c 'n' ''), [ref]$entryN)
4375:        $rec = [pscustomobject]@{ At = $at; Order = $order; N = $entryN; Ok = ($outcome -eq 'usable reply'); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Until = $at.AddMinutes(60) }
4376:        if (-not $rec.Ok) {
4377:            $reference = $at
4378:            $pf = Get-PropertyValue $c 'provider_failure' $null
4379:            if ($null -ne $pf) {
4380:                $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
4381:                # An entry recorded as auth whose message says usage limit / quota / rate limit
4382:                # counts as quota (Get-ProviderFailureClass's rule, applied when the ledger is
4383:                # READ): a 401/403 with a usage-limit text recorded before that rule existed
4384:                # (Kimi Code's 5-hour limit) stops refusing the endpoint for 24 h as an auth
4385:                # failure - without anyone editing the ledger.
4386:                if ($rec.Class -eq 'auth' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:QuotaTextPattern) { $rec.Class = 'quota' }
4387:                $rec.Code = [string](Get-PropertyValue $pf 'code' '')
4388:                $rec.Message = [string](Get-PropertyValue $pf 'message' '')
4389:                $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
4390:                if ($null -ne $pfWhen) { $reference = $pfWhen }
4391:                $recorded = Get-PropertyValue $pf 'retry_after' $null
4392:                if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
4393:            } else {
4394:                # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
4395:                $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
4396:                $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
4397:                $rec.Code = $parsedOutcome.Code
4398:                $rec.Message = $parsedOutcome.Message
4399:            }
4400:            # an entry recorded without retry_after: read the reset time from its message now
4401:            if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
4402:            else {
4403:                $rec.RetryAfter = Get-RetryAfter -Message $rec.Message -Reference $reference -ReferenceOffset
4404:                if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'message (reference offset)' }
4405:            }
4406:            if ($null -ne $rec.RetryAfter) {
4407:                $rec.RetryAfterIso = Format-OffsetIso $rec.RetryAfter
4408:                $rec.Until = $rec.RetryAfter
4409:            }
4410:            if ($rec.Message.Length -gt 100) { $rec.Message = $rec.Message.Substring(0, 100) }
4411:        }
4412:        $records.Add($rec)
4413:    }
4414:    $sorted = @($records | Sort-Object -Property @{ Expression = { $_.Order }; Descending = $true }, @{ Expression = { $_.N }; Descending = $true })
4415:    $auth = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'auth' }) | Select-Object -First 1
4416:    if ($auth -and -not $auth.Ok -and $auth.AgeMinutes -le 24 * 60) { $h.Auth = $auth }
4417:    $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
4418:    if ($quota -and -not $quota.Ok) {
4419:        if ($null -ne $quota.RetryAfter) {
4420:            if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
4421:        } elseif ($quota.AgeMinutes -le 60) {
4422:            $h.Quota = $quota
4423:        }
4424:    }
4425:    $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
4426:    $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4427:    $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4428:    $h.RecentUsable = @($sorted | Where-Object { $_.Ok -and $_.Age -le 60 }) | Select-Object -First 1
4429:    return $h
4430:}
