1:# FAKE muse (Meta's Muse Code CLI) for harness-muse.ps1 - never calls any model and never reads
2:# a credential. Started through fake-muse.cmd, which hands the command line over as
3:# FAKE_MUSE_ARGS (parsed here with the MS C runtime quoting the bridge uses, so a path with
4:# spaces arrives whole). `exec --json` prints MSP JSONL records shaped like the real CLI's
5:# (Muse Code 1.4.0, a sanitized probe of a completed `muse exec --json --output-schema` run with
6:# a read_file tool call): every record {schema_version, id, stream{kind: session, id},
7:# sequence, recorded_at, record_type, durability, causation_id, payload_type,
8:# payload_schema_version, payload}; payloads runtime.command.accepted, session.run.linked,
9:# run.model.configured {provider_id meta, profile_id tbh, model_id, display_label, source},
10:# turn.input.user, run.lifecycle.started, task.stream.linked, task.lifecycle.* (a model response
11:# task and a tool.read_file task), tool.result, run.output.delta and ONE run.terminal.<kind>
12:# {kind run_terminal, terminal, text, reason}. Ids are generated (no real session id).
13:# It is STRICT about the real flags: any other argument, a missing value, an unreadable
14:# --prompt-file or --output-schema, a --reasoning-effort outside the CLI's list, an
15:# --approval-mode other than never or a --max-model-steps that is not a positive integer ->
16:# stderr "error: ..." and exit 2 (the CLI's usage error).
17:#   `--version`                 prints "muse <FAKE_MUSE_VERSION or 9.9.9-fake>";
18:#                               FAKE_MUSE_VERSION_LOG=<path> gets one line per call
19:#   exec:
20:#   FAKE_MUSE_REPLY=<file>        the terminal text (default {"answer":"fake"})
21:#   FAKE_MUSE_RESUME_REPLY=<file> on a --session-id turn (the bridge's format repair or a
22:#                                 resume): this reply instead
23:#   FAKE_MUSE_TERMINAL=<kind>     failed | cancelled (default completed); text null, reason
24:#                                 FAKE_MUSE_REASON; exit 1 unless FAKE_MUSE_EXIT is set
25:#   FAKE_MUSE_REASON=<text>       payload.reason of the terminal record
26:#   FAKE_MUSE_EXIT=<n>            exit n after the records (1, 2, 130, 143 ...)
27:#   FAKE_MUSE_USAGE_ERROR=1       no records: stderr "error: ..." and exit 2
28:#   FAKE_MUSE_STDERR=<text>       one more stderr line (after the two informational ones)
29:#   FAKE_MUSE_SESSION=other       on --session-id: a NEW session (a mismatch); =notuuid: the
30:#                                 session id is not a uuid; default: the requested id on
31:#                                 --session-id, a new uuid otherwise
32:#   FAKE_MUSE_TWOSESSIONS=1       the second half of the records on another session stream
33:#   FAKE_MUSE_MODEL=<model>       run.model.configured serves this model (a drift);
34:#                                 FAKE_MUSE_NOMODEL=1: no run.model.configured record
35:#   FAKE_MUSE_SCHEMA_VERSION=<n>  every record's schema_version (default 1)
36:#   FAKE_MUSE_TWOTERMINALS=1      two run_terminal records;  FAKE_MUSE_NOTERMINAL=1: none
37:#   FAKE_MUSE_TERMINAL_STREAM=run the terminal record on a run stream (off the session)
38:#   FAKE_MUSE_PARTIAL=1           a truncated JSON line after the terminal (no newline)
39:#   FAKE_MUSE_WRITE=<rel path>    writes that file (relative to the working directory) on a
40:#                                 turn without --session-id (=<path>|all: on every turn)
41:#   FAKE_MUSE_HANG=1              sleeps 60 s after the first records (a timeout kill)
42:#   FAKE_MUSE_DELAY_MS=<ms>       sleeps that long before the answer
43:#   FAKE_MUSE_LOG=<path>          RAW: <FAKE_MUSE_ARGS>, ARG: <each argument>, STDIN-BYTES: <n>,
44:#                                 PROMPT-FILE: <path>, then PROMPT: and the prompt file's text
45:#                                 (a turn without --session-id); FAKE_MUSE_RESUME_LOG=<path>: the
46:#                                 same for a --session-id turn
47:#   FAKE_MUSE_COUNT=<path>        one line per exec turn ("exec <session or new>")
48:#   FAKE_MUSE_PIDFILE=<path>      its pid
49:$ErrorActionPreference = 'Stop'
50:$u8 = New-Object System.Text.UTF8Encoding($false)
51:$raw = [string]$env:FAKE_MUSE_ARGS
52:function Out-Bytes { param([string]$Text) $b = $u8.GetBytes($Text); $s = [Console]::OpenStandardOutput(); $s.Write($b, 0, $b.Length); $s.Flush() }
53:function Err-Bytes { param([string]$Text) $b = $u8.GetBytes($Text + "`r`n"); $s = [Console]::OpenStandardError(); $s.Write($b, 0, $b.Length); $s.Flush() }
54:function J { param($Obj) return (ConvertTo-Json -InputObject $Obj -Compress -Depth 30) }
55:# (retried on a sharing violation: parallel panel members share the harness's variables)
56:function Invoke-FakeWrite { param([scriptblock]$Do) for ($i = 0; $i -lt 40; $i++) { try { & $Do; return } catch { Start-Sleep -Milliseconds 50 } }; & $Do }
57:function Stop-Usage { param([string]$Why) Err-Bytes "error: $Why"; Err-Bytes 'Usage: muse exec [OPTIONS]'; exit 2 }
58:
59:# The command line, split by the MS C runtime rules the bridge quotes for: blanks separate
60:# arguments outside double quotes; "" inside quotes is one quote.
61:function Split-CommandLine {79:    if ($have) { $args2.Add($sb.ToString()) }82:$argv = Split-CommandLine $raw
83:
84:if ($argv.Count -ge 1 -and $argv[0] -eq '--version') {
85:    if ($env:FAKE_MUSE_VERSION_LOG) { Invoke-FakeWrite { [IO.File]::AppendAllText($env:FAKE_MUSE_VERSION_LOG, "version`n") } }
86:    Out-Bytes ("muse $(if ($env:FAKE_MUSE_VERSION) { $env:FAKE_MUSE_VERSION } else { '9.9.9-fake' })`n")
87:    exit 0
88:}
89:if ($argv.Count -lt 1 -or $argv[0] -ne 'exec') { Stop-Usage "unrecognized subcommand '$(if ($argv.Count -ge 1) { $argv[0] })'" }
90:
91:# ---- exec: the real flags only
92:$valueFlags = @('--prompt-file', '--output-schema', '--model', '--reasoning-effort', '--approval-mode', '--max-model-steps', '--session-id')
93:$switchFlags = @('--json', '--no-foreign-personal-context', '--disable-web-tools', '--disable-write', '--disable-shell')
94:$opt = @{}
95:for ($i = 1; $i -lt $argv.Count; $i++) {
96:    $a = $argv[$i]
97:    if ($switchFlags -ccontains $a) { $opt[$a] = $true; continue }
98:    if ($valueFlags -ccontains $a) {
99:        if ($i + 1 -ge $argv.Count) { Stop-Usage "a value is required for '$a'" }
100:        $opt[$a] = $argv[$i + 1]; $i++; continue
101:    }
102:    Stop-Usage "unexpected argument '$a' found"
103:}
104:if (-not $opt['--json']) { Stop-Usage 'the fake only speaks --json' }
105:if (-not $opt['--prompt-file']) { Stop-Usage "the following required argument was not provided: --prompt-file (or a prompt)" }
106:$promptFile = [string]$opt['--prompt-file']
107:if (-not (Test-Path -LiteralPath $promptFile -PathType Leaf)) { Stop-Usage "cannot read prompt file '$promptFile'" }
108:if ($opt['--output-schema'] -and -not (Test-Path -LiteralPath ([string]$opt['--output-schema']) -PathType Leaf)) { Stop-Usage "cannot read output schema '$($opt['--output-schema'])'" }
109:if (-not $opt['--model']) { Stop-Usage 'the fake needs --model' }
110:if ($opt['--reasoning-effort'] -and @('none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra') -cnotcontains [string]$opt['--reasoning-effort']) { Stop-Usage "invalid value '$($opt['--reasoning-effort'])' for '--reasoning-effort'" }
111:if ($opt['--approval-mode'] -and [string]$opt['--approval-mode'] -cne 'never') { Stop-Usage "the fake takes --approval-mode never only" }
112:$steps = 0
113:if ($opt['--max-model-steps'] -and (-not [int]::TryParse([string]$opt['--max-model-steps'], [ref]$steps) -or $steps -lt 1)) { Stop-Usage "invalid value '$($opt['--max-model-steps'])' for '--max-model-steps'" }
114:if ($env:FAKE_MUSE_USAGE_ERROR -eq '1') { Stop-Usage "unexpected argument '--fake-usage-error' found" }
115:
116:$stdinBytes = @()
117:try {
118:    $ms = New-Object System.IO.MemoryStream
119:    [Console]::OpenStandardInput().CopyTo($ms)
120:    $stdinBytes = $ms.ToArray()
121:} catch { $stdinBytes = @() }
122:$promptText = [IO.File]::ReadAllText($promptFile, $u8)
123:$conv = [string]$opt['--session-id']
124:$model = [string]$opt['--model']
125:$log = if ($conv -and $env:FAKE_MUSE_RESUME_LOG) { $env:FAKE_MUSE_RESUME_LOG } elseif (-not $conv) { $env:FAKE_MUSE_LOG } else { '' }
126:if ($log) {
127:    $lines = New-Object System.Collections.Generic.List[string]
128:    $lines.Add("RAW: $raw")
129:    foreach ($a in $argv) { $lines.Add("ARG: $a") }
130:    $lines.Add("STDIN-BYTES: $($stdinBytes.Length)")
131:    $lines.Add("PROMPT-FILE: $promptFile")
132:    $lines.Add('PROMPT:')
133:    Invoke-FakeWrite { [IO.File]::WriteAllText($log, (($lines.ToArray() -join "`n") + "`n" + $promptText), $u8) }
134:}
135:if ($env:FAKE_MUSE_COUNT) { Invoke-FakeWrite { [IO.File]::AppendAllText($env:FAKE_MUSE_COUNT, "exec $(if ($conv) { $conv } else { 'new' })`n") } }
136:if ($env:FAKE_MUSE_PIDFILE) { Invoke-FakeWrite { [IO.File]::WriteAllText($env:FAKE_MUSE_PIDFILE, "$PID") } }
137:
138:# ---- the session and the records
139:$session = [guid]::NewGuid().ToString()
140:if ($conv -and $env:FAKE_MUSE_SESSION -ne 'other') { $session = $conv }
141:if ($env:FAKE_MUSE_SESSION -eq 'notuuid') { $session = 'session-1' }
142:$command = [guid]::NewGuid().ToString()
143:$schemaVersion = 1
144:if ($env:FAKE_MUSE_SCHEMA_VERSION) { $schemaVersion = [int]$env:FAKE_MUSE_SCHEMA_VERSION }
145:$script:seq = 0
146:$script:streamId = $session
147:function Rec {
148:    param([string]$RecordType, [string]$PayloadType, $Payload, [string]$Durability = 'durable', [string]$StreamKind = 'session')
149:    $script:seq++
150:    $o = [pscustomobject][ordered]@{
151:        schema_version         = $schemaVersion
152:        id                     = ('018f0000-0000-7000-8000-{0:x12}' -f (50000 + 2 * $script:seq))
153:        stream                 = [pscustomobject][ordered]@{ kind = $StreamKind; id = $(if ($StreamKind -eq 'session') { $script:streamId } else { $command }) }
154:        sequence               = $script:seq
155:        recorded_at            = [long]1780531400000000 + 2 * $script:seq
156:        record_type            = $RecordType
157:        durability             = $Durability
158:        causation_id           = $command
159:        payload_type           = $PayloadType
160:        payload_schema_version = 1
161:        payload                = $Payload
162:    }
163:    Out-Bytes ((J $o) + "`n")
